  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT ' ''open'',                     // открытый ответ\n        ''matching'',                 // соответствие\n        ''multiple_choice_single'',   // один правильный\n        ''multiple_choice_multiple'', // несколько правильных\n        ''fill_in_blank'',            // пропущенные слова\n        ''true_false'',               // верно/неверно',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `question_types_name_unique` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

