INSERT INTO `contests` (`id`, `topic_id`, `olympiad_level_id`, `title`, `description`, `start_time`, `end_time`, `frozen_at`, `status`, `scoring_type`, `type`, `password`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 9, NULL, 'Строки', 'Контест посвешён строкам', '2026-04-28 12:00:00', '2026-04-29 12:00:00', NULL, 'running', 'acm_icpc', 'open', NULL, 2, '2026-04-21 03:04:55', '2026-04-29 03:55:52'),
(2, 1, NULL, 'Beginb', NULL, '2026-05-01 12:00:00', '2027-01-01 12:00:00', NULL, 'upcoming', 'acm_icpc', 'open', NULL, 2, '2026-05-02 01:07:07', '2026-09-30 17:09:20'),
(3, 2, NULL, 'Строки', 'Строки', '2026-08-01 12:00:00', '2026-09-01 12:00:00', NULL, 'finished', 'acm_icpc', 'open', NULL, 289, '2026-08-31 02:07:27', '2026-09-13 07:43:31'),
(4, NULL, NULL, 'Практика по курсу «C++»', 'Служебный контест — держит задачи, прикреплённые к шагам курса C++ (сгенерирован сидером).', '2025-08-31 16:45:50', '2031-08-31 16:45:50', NULL, 'upcoming', 'acm_icpc', 'open', NULL, 1, '2026-08-31 13:45:50', '2026-08-31 13:45:50'),
(5, 36, NULL, 'Реализация(easy problems)', 'Реализация — это написание кода по уже придуманному алгоритму.', '2026-09-06 12:00:00', NULL, NULL, 'upcoming', 'olympiad', 'open', NULL, 39, '2026-09-06 10:47:59', '2026-09-06 11:46:14'),
(6, 36, NULL, 'Реализация(middle problems)', NULL, '2026-09-06 12:00:00', NULL, NULL, 'upcoming', 'olympiad', 'open', NULL, 39, '2026-09-06 11:46:53', '2026-09-06 11:47:09'),
(7, 11, NULL, 'бинарный поиск(easy problems)', NULL, NULL, NULL, NULL, 'upcoming', 'olympiad', 'open', NULL, 39, '2026-09-10 06:46:47', '2026-09-10 06:46:47'),
(8, 11, NULL, 'бинарный поиск(midlde problems)', NULL, NULL, NULL, NULL, 'upcoming', 'acm_icpc', 'open', NULL, 39, '2026-09-10 08:41:03', '2026-09-10 08:41:03'),
(9, 37, NULL, 'Теория графов Level I', 'Теория графов — это раздел математики и информатики, который изучает связи между различными объектами. Графы помогают представить в удобном виде дороги между городами, связи между людьми, компьютерные сети, маршруты и многие другие задачи.\r\n\r\nНа начальном уровне мы познакомимся с основными понятиями: вершина, ребро, степень вершины, путь, цикл и связность графа. Также научимся изображать графы и решать простые задачи с их использованием.\r\n\r\nИзучение теории графов развивает логическое мышление, умение находить связи и строить эффективные решения, поэтому эта тема особенно важна для программирования и олимпиадных задач.', NULL, NULL, NULL, 'upcoming', 'acm_icpc', 'open', NULL, 40, '2026-09-24 03:14:46', '2026-09-24 03:14:46'),
(10, NULL, 1, 'Олимпиадаи мактабӣ', NULL, '2026-09-30 07:00:00', '2026-10-31 12:00:00', NULL, 'upcoming', 'olympiad', 'open', NULL, 39, '2026-09-30 03:58:50', '2026-09-30 04:05:55'),
(11, 38, NULL, 'Begin', 'Ввод и вывод данных, оператор присваивания\n\nВсе входные и выходные данные в заданиях этой группы являются вещественными числами.\n\nВвод: числа по одному в строке. Вывод: результаты по одному в строке, ровно с двумя знаками после точки.\n\nЗадания: М. Э. Абрамян, Programming Taskbook, https://ptaskbook.com/ru/tasks/begin.php', NULL, NULL, NULL, 'upcoming', 'io', 'open', NULL, 39, '2026-09-30 17:09:48', '2026-09-30 17:09:48'),
(12, 38, NULL, 'Integer', 'Целые числа\n\nВсе входные и выходные данные в заданиях этой группы являются целыми числами. Все числа, для которых указано количество цифр (двузначное число, трехзначное число и т. д.), считаются положительными.\n\nВвод: числа по одному в строке. Вывод: результаты по одному в строке, ровно с двумя знаками после точки.\n\nЗадания: М. Э. Абрамян, Programming Taskbook, https://ptaskbook.com/ru/tasks/integer.php', NULL, NULL, NULL, 'upcoming', 'io', 'open', NULL, 39, '2026-09-30 17:09:59', '2026-09-30 17:09:59');
