INSERT INTO `olympiad_levels` (`id`, `slug`, `name`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'city', 'Городской', 10, '2026-09-29 15:28:49', '2026-09-29 15:28:49'),
(2, 'region', 'Областной', 20, '2026-09-29 15:28:49', '2026-09-29 15:28:49'),
(3, 'republic', 'Республиканский', 30, '2026-09-29 15:28:49', '2026-09-29 15:28:49');
INSERT INTO `problems` (`id`, `contest_id`, `title`, `statement`, `notes`, `time_limit`, `memory_limit`, `input`, `output`, `score`, `order_index`, `created_at`, `updated_at`, `skill_id`, `complexity`, `solution_source`, `solution_language_id`, `tests_status`, `tests_log`, `tests_generated_at`, `hidden_from_archive`) VALUES
(1, 1, 'a+b', '<p>a+b sdcsdcsdcsdcsdc</p>\r\n<p>sdc</p>\r\n<p>sdcds</p>', '<p>2+3=5</p>', 1, 256, '<p>a b</p>', '<p>s</p>', 50, 0, '2026-06-10 09:07:21', '2026-06-10 09:07:21', 1, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(2, 3, 'a+b', '<p>Cуммаи ду адади додашударо ёбед</p>', NULL, 1, 256, '<p>1 2</p>', '<p>3</p>', 5, 0, '2026-08-31 02:08:41', '2026-09-30 04:02:01', 4, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(3, 3, 'sdcs', '<p>dsdsdsd</p>', '<p>dsd</p>', 1, 256, '<p>sdsd</p>', '<p>dsd</p>', 70, 0, '2026-08-31 03:15:22', '2026-08-31 03:15:22', 2, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(4, 4, 'Hello, C++!', '<p>Напишите программу, которая считывает с ввода одно слово — имя пользователя — и выводит приветствие в формате <code>Hello, &lt;имя&gt;!</code></p>', NULL, 2, 64, 'Одна строка — имя (без пробелов).', 'Строка вида «Hello, Имя!».', 100, 1, '2026-08-31 13:45:50', '2026-08-31 13:45:50', 4, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(5, 4, 'Площадь прямоугольника', '<p>Считайте с ввода два целых числа — длины сторон прямоугольника <code>a</code> и <code>b</code> — и выведите его площадь.</p>', NULL, 2, 64, 'Два целых числа через пробел или перенос строки: a и b (1 ≤ a, b ≤ 1000).', 'Одно целое число — площадь.', 100, 2, '2026-08-31 13:45:50', '2026-08-31 13:45:50', 4, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(6, 4, 'Скидка на товар', '<p>Считайте цену товара (целое число) и процент скидки (целое число от 0 до 100). Выведите итоговую цену после скидки: <code>price - price * discount / 100</code>, где деление выполняется нацело.</p>', NULL, 2, 64, 'Два целых числа через пробел: price и discount.', 'Одно целое число — цена после скидки.', 100, 3, '2026-08-31 13:45:50', '2026-08-31 13:45:50', 4, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(7, 4, 'Високосный год', '<p>Считайте год (целое число) и определите, является ли он високосным. Год високосный, если он делится на 4, но не делится на 100 &mdash; либо делится на 400.</p>', NULL, 2, 64, '<p>Одно целое число &mdash; год.</p>', '<p><code>YES</code>, если год високосный, иначе <code>NO</code>.</p>', 10, 4, '2026-08-31 13:45:50', '2026-09-30 04:02:51', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(8, 4, 'Сумма цифр числа', '<p>Считайте натуральное число и выведите сумму его цифр.</p>', NULL, 2, 64, 'Одно целое число N (1 ≤ N ≤ 10^9).', 'Сумма цифр числа N.', 100, 5, '2026-08-31 13:45:50', '2026-08-31 13:45:50', 1, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(9, 4, 'Максимум и минимум в массиве', '<p>Считайте число элементов n, затем n целых чисел. Выведите через пробел максимальное и минимальное значение.</p>', NULL, 2, 64, '<p>Первая строка &mdash; n (1 &le; n &le; 1000). Вторая строка &mdash; n чисел.</p>', '<p>Два числа через пробел: максимум и минимум.</p>', 20, 6, '2026-08-31 13:45:50', '2026-09-30 04:03:55', 2, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(10, 4, 'Разворот строки', '<p>Считайте строку (без пробелов) и выведите её в перевёрнутом порядке.</p>', NULL, 2, 64, 'Одна строка длиной не более 1000 символов.', 'Перевёрнутая строка.', 100, 7, '2026-08-31 13:45:51', '2026-08-31 13:45:51', 4, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(11, 4, 'Числа Фибоначчи', '<p>Считайте номер n и выведите n-е число Фибоначчи, если F(1) = 1, F(2) = 1, F(n) = F(n-1) + F(n-2).</p>', NULL, 2, 64, 'Одно целое число n (1 ≤ n ≤ 30).', 'Число Фибоначчи F(n).', 100, 8, '2026-08-31 13:45:51', '2026-08-31 13:45:51', 1, 'medium', NULL, NULL, NULL, NULL, NULL, 0),
(12, 4, 'Обмен значений через указатели', '<p>Напишите программу: считайте два целых числа a и b, поменяйте их местами с помощью функции, принимающей указатели, и выведите результат через пробел.</p>', NULL, 2, 64, 'Два целых числа через пробел.', 'Два числа через пробел — в обратном порядке.', 100, 9, '2026-08-31 13:45:51', '2026-08-31 13:45:51', 4, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(13, 4, 'Класс Point', '<p>Реализуйте класс <code>Point</code> с полями <code>x</code>, <code>y</code> (тип <code>double</code>) и методом, вычисляющим расстояние до начала координат. Считайте координаты точки и выведите расстояние с двумя знаками после запятой.</p>', NULL, 2, 64, 'Два вещественных числа x и y через пробел.', 'Расстояние до начала координат, округлённое до 2 знаков после запятой.', 100, 10, '2026-08-31 13:45:51', '2026-08-31 13:45:51', 10, 'easy', NULL, NULL, NULL, NULL, NULL, 0),
(14, 4, 'Уникальные числа', '<p>Считайте n целых чисел и выведите количество различных (уникальных) значений среди них.</p>', NULL, 2, 64, 'Первая строка — n (1 ≤ n ≤ 1000). Вторая строка — n целых чисел.', 'Одно число — количество уникальных значений.', 100, 11, '2026-08-31 13:45:51', '2026-08-31 13:45:51', 2, 'medium', NULL, NULL, NULL, NULL, NULL, 0),
(15, 4, 'Безопасное деление', '<p>Считайте два целых числа a и b. Если b равно нулю &mdash; используя <code>try/catch</code> и <code>throw</code>, выведите строку <code>Error</code>; иначе выведите результат целочисленного деления a / b.</p>', NULL, 2, 64, '<p>Два целых числа через пробел.</p>', '<p>Результат деления или строка Error.</p>', 10, 12, '2026-08-31 13:45:51', '2026-09-30 04:02:38', 4, 'medium', NULL, 1, NULL, NULL, NULL, 0),
(16, 4, 'Мини-калькулятор', '<p>Считайте строку в формате <code>a OP b</code>, где a и b — целые числа, а OP — один из символов <code>+ - * /</code> (например, <code>\"6 + 3\"</code>). Выведите результат операции. Если OP — <code>/</code> и b равно 0, выведите <code>Error</code>. Деление выполняйте нацело.</p>', NULL, 2, 64, 'Одна строка вида «число операция число», разделённых пробелами.', 'Число-результат или строка Error.', 100, 13, '2026-08-31 13:45:51', '2026-08-31 13:45:51', 1, 'medium', NULL, NULL, NULL, NULL, NULL, 0),
(17, 4, 'scsdcscsdcsd', '<p>scdssdcs</p>', '<p>sdcsddsd</p>', 1, 256, '<p>sdcsdc</p>', '<p>scdsd</p>', 50, 0, '2026-09-04 14:45:18', '2026-09-07 13:31:22', 1, 'easy', NULL, 2, NULL, NULL, '2026-09-07 12:36:42', 0),
(18, 5, 'Переворот числа', '<p data-start=\"21\" data-end=\"81\" class=\"PDq2pG_selectionAnchorContainer\">Дано целое число <code data-start=\"38\" data-end=\"41\">n</code>. Выведите его цифры в обратном порядке.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"83\" data-end=\"99\"><strong data-start=\"83\" data-end=\"99\">Ограничения:</strong></p>\r\n<ul data-start=\"100\" data-end=\"149\">\r\n<li data-section-id=\"33kxdd\" data-start=\"100\" data-end=\"116\"><code data-start=\"102\" data-end=\"116\">1 &le; n &le; 10^9</code></li>\r\n<li data-section-id=\"1fmmv0f\" data-start=\"117\" data-end=\"149\"><code data-start=\"119\" data-end=\"122\">n</code> не содержит ведущих нулей.</li>\r\n</ul>', NULL, 1, 256, '<p>В единственной строке дано целое число <code data-start=\"58\" data-end=\"61\">n</code>.</p>', '<p>Выведите цифры числа <code data-start=\"105\" data-end=\"108\">n</code> в обратном порядке.</p>', 50, 0, '2026-09-06 10:56:54', '2026-09-06 10:56:54', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(20, 5, 'Подсчёт чётных', '<p>Дано <code data-start=\"43\" data-end=\"46\">n</code> целых чисел. Посчитайте количество чётных чисел.</p>', NULL, 1, 256, '<p>В первой строке дано число <code data-start=\"146\" data-end=\"149\">n</code>.<br data-start=\"150\" data-end=\"153\">Во второй строке даны <code data-start=\"175\" data-end=\"178\">n</code> целых чисел.</p>', '<p>Выведите количество чётных чисел.</p>', 50, 0, '2026-09-06 11:18:45', '2026-09-06 11:18:45', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(21, 5, 'Максимальный элемент', '<p>Дан массив из <code data-start=\"314\" data-end=\"317\">n</code> чисел. Найдите максимальный элемент.</p>', NULL, 1, 256, '<p>В первой строке дано <code data-start=\"399\" data-end=\"402\">n</code>.<br data-start=\"403\" data-end=\"406\">Во второй строке даны <code data-start=\"428\" data-end=\"431\">n</code> чисел.</p>', '<p data-start=\"440\" data-end=\"501\" class=\"PDq2pG_selectionAnchorContainer\">Выведите максимальный элемент массива.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>', 50, 0, '2026-09-06 11:29:24', '2026-09-06 11:29:24', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(22, 5, 'Замена символов', '<p>Дана строка, состоящая только из <code data-start=\"784\" data-end=\"787\">A</code> и <code data-start=\"790\" data-end=\"793\">B</code>. Замените каждый <code data-start=\"811\" data-end=\"814\">A</code> на <code data-start=\"818\" data-end=\"821\">B</code>, а каждый <code data-start=\"832\" data-end=\"835\">B</code> на <code data-start=\"839\" data-end=\"842\">A</code>.</p>', NULL, 1, 256, '<p data-start=\"845\" data-end=\"898\" class=\"PDq2pG_selectionAnchorContainer\">В одной строке дана строка <code data-start=\"894\" data-end=\"897\">s</code>.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>', '<p>Выведите изменённую строку.</p>', 50, 0, '2026-09-06 11:31:19', '2026-09-06 11:31:19', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(23, 5, 'Светофор', '<p>Дана буква <code data-start=\"1000\" data-end=\"1003\">R</code>, <code data-start=\"1005\" data-end=\"1008\">Y</code> или <code data-start=\"1013\" data-end=\"1016\">G</code>. Определите действие светофора.</p>', NULL, 1, 256, '<p>В одной строке дана одна буква: <code data-start=\"1104\" data-end=\"1107\">R</code>, <code data-start=\"1109\" data-end=\"1112\">Y</code> или <code data-start=\"1117\" data-end=\"1120\">G</code>.</p>', '<ul>\r\n<li data-section-id=\"hta968\" data-start=\"1146\" data-end=\"1160\"><code data-start=\"1148\" data-end=\"1151\">R</code> &rarr; <code data-start=\"1154\" data-end=\"1160\">STOP</code><span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></li>\r\n<li data-section-id=\"22bt4\" data-start=\"1161\" data-end=\"1175\"><code data-start=\"1163\" data-end=\"1166\">Y</code> &rarr; <code data-start=\"1169\" data-end=\"1175\">WAIT</code></li>\r\n<li data-section-id=\"7fexsl\" data-start=\"1176\" data-end=\"1188\" data-is-last-node=\"\"><code data-start=\"1178\" data-end=\"1181\">G</code> &rarr; <code data-start=\"1184\" data-end=\"1188\" data-is-last-node=\"\">GO</code></li>\r\n</ul>', 50, 0, '2026-09-06 11:32:51', '2026-09-06 11:32:51', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(24, 6, 'Шахматная ладья', '<p>Дана шахматная доска размером <code data-start=\"212\" data-end=\"219\">n &times; n</code> и две клетки. Определите, может ли ладья попасть из первой клетки во вторую за один ход.</p>', NULL, 1, 256, '<p data-start=\"310\" data-end=\"379\" class=\"PDq2pG_selectionAnchorContainer\">В первой строке дано число <code data-start=\"359\" data-end=\"362\">n</code> (<code data-start=\"364\" data-end=\"377\">1 &le; n &le; 10⁹</code>).<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"381\" data-end=\"460\">Во второй строке даны четыре числа <code data-start=\"416\" data-end=\"432\">x₁, y₁, x₂, y₂</code> (<code data-start=\"434\" data-end=\"458\">1 &le; x₁, y₁, x₂, y₂ &le; n</code>).</p>', '<div class=\"qMYqUG_convSearchResultHighlightRoot\">\r\n<div class=\"\" data-turn-id-container=\"request-WEB:2057a767-d550-4917-b501-04b7c3807a66-15\" data-is-intersecting=\"true\">\r\n<section class=\"text-token-text-primary w-full focus:outline-none has-data-writing-block:pointer-events-none [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto R6Vx5W_threadScrollVars scroll-mb-[calc(var(--scroll-root-safe-area-inset-bottom,0px)+var(--thread-response-height))] scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" data-turn-id=\"request-WEB:2057a767-d550-4917-b501-04b7c3807a66-15\" data-turn-id-container=\"request-WEB:2057a767-d550-4917-b501-04b7c3807a66-15\" data-testid=\"conversation-turn-32\" data-turn=\"assistant\">\r\n<div class=\"text-base my-auto mx-auto pb-8 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\r\n<div data-conversation-screenshot-content=\"\" class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\">\r\n<div class=\"flex max-w-full flex-col gap-4 grow\">\r\n<div data-message-author-role=\"assistant\" data-message-id=\"c494b8f0-fccf-485d-878c-ad62d7a30703\" dir=\"auto\" data-message-model-slug=\"gpt-5-6-mini\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\">\r\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\r\n<div class=\"markdown prose dark:prose-invert wrap-break-word w-full dark markdown-new-styling\">\r\n<p data-start=\"462\" data-end=\"577\" data-is-last-node=\"\" data-is-only-node=\"\" class=\"PDq2pG_selectionAnchorContainer\">Выведите <code data-start=\"494\" data-end=\"499\">YES</code>, если ладья может попасть из первой клетки во вторую за один ход, иначе <code data-start=\"572\" data-end=\"576\">NO</code>.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"z-0 flex min-h-[46px] justify-start\"></div>\r\n<div class=\"mt-3 w-full empty:hidden has-[&gt;_:empty]:hidden\">\r\n<div class=\"text-center\"></div>\r\n</div>\r\n</div>\r\n<div data-conversation-screenshot-content=\"\" class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1\">\r\n<div></div>\r\n</div>\r\n</div>\r\n</section>\r\n</div>\r\n</div>', 50, 0, '2026-09-06 11:54:34', '2026-09-06 11:54:34', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(25, 6, 'Смена направления', '<p data-start=\"26\" data-end=\"124\" class=\"PDq2pG_selectionAnchorContainer\">Робот движется по прямой дороге. В каждый момент времени он находится на некоторой координате <code data-start=\"120\" data-end=\"123\">x</code>.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"126\" data-end=\"272\" class=\"\">Если следующая координата больше предыдущей &mdash; робот движется <strong data-start=\"187\" data-end=\"197\">вправо</strong>.<br data-start=\"198\" data-end=\"201\">Если следующая координата меньше предыдущей &mdash; робот движется <strong data-start=\"262\" data-end=\"271\">влево</strong>.</p>\r\n<p data-start=\"274\" data-end=\"335\" class=\"\">Посчитайте, <strong data-start=\"286\" data-end=\"334\">сколько раз робот менял направление движения</strong>.<strong data-start=\"337\" data-end=\"356\"></strong></p>', NULL, 1, 256, '<p data-start=\"358\" data-end=\"429\" class=\"PDq2pG_selectionAnchorContainer\">В первой строке дано число <code data-start=\"385\" data-end=\"388\">n</code> (<code data-start=\"390\" data-end=\"404\">2 &le; n &le; 10^5</code>) &mdash; количество координат.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"431\" data-end=\"529\">Во второй строке даны <code data-start=\"453\" data-end=\"456\">n</code> целых чисел <code data-start=\"469\" data-end=\"486\">x₁, x₂, ..., xₙ</code> (<code data-start=\"488\" data-end=\"507\">-10^9 &le; xᵢ &le; 10^9</code>) &mdash; координаты робота.</p>\r\n<p data-start=\"531\" data-end=\"592\" class=\"\">Гарантируется, что соседние координаты различны: <code data-start=\"580\" data-end=\"591\">xᵢ &ne; xᵢ₊₁</code>.</p>', '<p>Выведите одно число &mdash; количество смен направления движения робота.</p>', 50, 0, '2026-09-06 11:58:18', '2026-09-06 11:58:18', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(27, 6, 'Робот', '<p data-start=\"14\" data-end=\"103\" class=\"PDq2pG_selectionAnchorContainer\">Робот находится в точке <code data-start=\"38\" data-end=\"46\">(0, 0)</code>. Он получает строку из команд и выполняет их по очереди.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"105\" data-end=\"113\">Команды:</p>\r\n<ul data-start=\"114\" data-end=\"189\">\r\n<li data-section-id=\"zfvq4w\" data-start=\"114\" data-end=\"132\"><code data-start=\"116\" data-end=\"119\">L</code> &mdash; шаг влево;</li>\r\n<li data-section-id=\"jd2q9b\" data-start=\"133\" data-end=\"152\"><code data-start=\"135\" data-end=\"138\">R</code> &mdash; шаг вправо;</li>\r\n<li data-section-id=\"yo9d2h\" data-start=\"153\" data-end=\"171\"><code data-start=\"155\" data-end=\"158\">U</code> &mdash; шаг вверх;</li>\r\n<li data-section-id=\"n0u0al\" data-start=\"172\" data-end=\"189\"><code data-start=\"174\" data-end=\"177\">D</code> &mdash; шаг вниз.</li>\r\n</ul>\r\n<p data-start=\"191\" data-end=\"258\">Определите конечные координаты робота после выполнения всех команд.</p>', NULL, 1, 256, '<p data-start=\"281\" data-end=\"349\" class=\"PDq2pG_selectionAnchorContainer\">В первой строке дано число <code data-start=\"308\" data-end=\"311\">n</code> (<code data-start=\"313\" data-end=\"327\">1 &le; n &le; 10^5</code>) &mdash; количество команд.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"351\" data-end=\"443\">Во второй строке дана строка <code data-start=\"380\" data-end=\"383\">s</code> длины <code data-start=\"390\" data-end=\"393\">n</code>, состоящая только из символов <code data-start=\"424\" data-end=\"427\">L</code>, <code data-start=\"429\" data-end=\"432\">R</code>, <code data-start=\"434\" data-end=\"437\">U</code>, <code data-start=\"439\" data-end=\"442\">D</code>.</p>', '<p>Выведите два числа <code data-start=\"486\" data-end=\"489\">x</code> и <code data-start=\"492\" data-end=\"495\">y</code> &mdash; конечные координаты робота.</p>', 50, 0, '2026-09-06 12:02:19', '2026-09-06 12:02:19', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(28, 6, 'Удаление одинаковых', '<p data-start=\"28\" data-end=\"83\" class=\"PDq2pG_selectionAnchorContainer\">Дана строка <code data-start=\"40\" data-end=\"43\">s</code>, состоящая из строчных английских букв.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"85\" data-end=\"173\">За одну операцию можно выбрать <strong data-start=\"116\" data-end=\"149\">две соседние одинаковые буквы</strong> и удалить их из строки.</p>\r\n<p data-start=\"175\" data-end=\"214\">Операции можно выполнять несколько раз.</p>\r\n<p data-start=\"216\" data-end=\"294\">Определите строку, которая останется после выполнения всех возможных операций.</p>', NULL, 1, 256, '<p data-start=\"317\" data-end=\"380\" class=\"PDq2pG_selectionAnchorContainer\">В первой строке дано число <code data-start=\"344\" data-end=\"347\">n</code> (<code data-start=\"349\" data-end=\"363\">1 &le; n &le; 10^5</code>) &mdash; длина строки.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"382\" data-end=\"464\">Во второй строке дана строка <code data-start=\"411\" data-end=\"414\">s</code> длины <code data-start=\"421\" data-end=\"424\">n</code>, состоящая из строчных английских букв.</p>', '<p data-start=\"488\" data-end=\"582\" class=\"PDq2pG_selectionAnchorContainer\">Выведите строку, которая останется после удаления всех возможных пар одинаковых соседних букв.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"584\" data-end=\"628\" data-is-last-node=\"\" data-is-only-node=\"\">Если строка станет пустой, выведите <code data-start=\"620\" data-end=\"627\">EMPTY</code>.</p>', 50, 0, '2026-09-06 12:04:50', '2026-09-06 12:04:50', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(29, 6, 'Покупки', '<p data-start=\"16\" data-end=\"67\" class=\"PDq2pG_selectionAnchorContainer\">У вас есть <code data-start=\"27\" data-end=\"30\">n</code> товаров. У каждого товара есть цена.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"69\" data-end=\"180\" class=\"\">У вас есть ровно <code data-start=\"86\" data-end=\"89\">m</code> денег. Вы хотите купить <strong data-start=\"114\" data-end=\"149\">максимальное количество товаров</strong>, не потратив больше <code data-start=\"170\" data-end=\"173\">m</code> денег.</p>\r\n<p data-start=\"182\" data-end=\"244\">Найдите максимальное количество товаров, которые можно купить.</p>', NULL, 1, 256, '<p data-start=\"267\" data-end=\"382\" class=\"PDq2pG_selectionAnchorContainer\">В первой строке даны два числа <code data-start=\"298\" data-end=\"301\">n</code> и <code data-start=\"304\" data-end=\"307\">m</code> (<code data-start=\"309\" data-end=\"323\">1 &le; n &le; 10^5</code>, <code data-start=\"325\" data-end=\"340\">1 &le; m &le; 10^14</code>) &mdash; количество товаров и количество денег.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\r\n<p data-start=\"384\" data-end=\"467\">Во второй строке даны <code data-start=\"406\" data-end=\"409\">n</code> чисел <code data-start=\"416\" data-end=\"433\">a₁, a₂, ..., aₙ</code> (<code data-start=\"435\" data-end=\"450\">1 &le; aᵢ &le; 10^9</code>) &mdash; цены товаров.</p>', '<p>Выведите максимальное количество товаров, которые можно купить.</p>', 50, 0, '2026-09-06 12:06:48', '2026-09-06 12:06:48', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(30, NULL, 'Двоичный поиск', '<p><span>Реализуйте алгоритм двоичного поиска.</span></p>', NULL, 1, 256, '<div class=\"input-specification\">\r\n<p>В первой строке входных данных содержатся натуральные числа<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-1\"><span><span class=\"mi\" id=\"MathJax-Span-3\">n</span><span></span></span><span></span></span><span>&nbsp;</span>и<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-4\"><span><span class=\"mi\" id=\"MathJax-Span-6\">k</span><span></span></span><span></span></span><span>&nbsp;</span>(<span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-7\"><span><span class=\"mrow\" id=\"MathJax-Span-8\"><span class=\"mn\" id=\"MathJax-Span-9\">1</span><span class=\"mo\" id=\"MathJax-Span-10\">&le;</span><span class=\"mi\" id=\"MathJax-Span-11\">n</span></span><span></span></span><span></span></span>,<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-12\"><span><span class=\"mrow\" id=\"MathJax-Span-13\"><span class=\"mi\" id=\"MathJax-Span-14\">k</span><span class=\"mo\" id=\"MathJax-Span-15\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-17\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-18\">5</span><span></span></span></span></span><span></span></span><span></span></span>)&nbsp;&mdash; длина массива и число запросов. Во второй строке содержатся<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-19\"><span><span class=\"mi\" id=\"MathJax-Span-21\">n</span><span></span></span><span></span></span><span>&nbsp;</span>элементов массива, отсортированного по неубыванию. В третьей строке содержатся<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-22\"><span><span class=\"mi\" id=\"MathJax-Span-24\">k</span><span></span></span><span></span></span><span>&nbsp;</span>запросов. Все элементы массива и запросы &mdash; целые числа, каждое из которых по модулю не превосходит<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-25\"><span><span><span><span class=\"mn\" id=\"MathJax-Span-28\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-29\">9</span><span></span></span></span><span></span></span><span></span></span>.</p>\r\n</div>', '<p><span>Требуется для каждого из&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-30\"><span><span class=\"mi\" id=\"MathJax-Span-32\">k</span><span></span></span><span></span></span><span>&nbsp;запросов вывести в отдельную строку&nbsp;</span><span class=\"tex-font-style-tt\">YES</span><span>, если это число встречается в массиве, и&nbsp;</span><span class=\"tex-font-style-tt\">NO</span><span>&nbsp;в противном случае.</span></p>', 50, 0, '2026-09-10 06:51:40', '2026-09-10 06:51:40', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(31, NULL, 'Ближайшее слева', '<div>\r\n<p>Дан массив из<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-1\"><span><span class=\"mi\" id=\"MathJax-Span-3\">n</span><span></span></span><span></span></span><span>&nbsp;</span>чисел, отсортированный по неубыванию, и<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-4\"><span><span class=\"mi\" id=\"MathJax-Span-6\">k</span><span></span></span><span></span></span><span>&nbsp;</span>запросов. Для каждого запроса выведите максимальный индекс элемента массива, не большего данного.</p>\r\n</div>', '<p><span>В первой строке входных данных содержатся числа&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-7\"><span><span class=\"mi\" id=\"MathJax-Span-9\">n</span><span></span></span><span></span></span><span>&nbsp;и&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-10\"><span><span class=\"mi\" id=\"MathJax-Span-12\">k</span><span></span></span><span></span></span><span>&nbsp;(</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-13\"><span><span class=\"mrow\" id=\"MathJax-Span-14\"><span class=\"mn\" id=\"MathJax-Span-15\">0</span><span class=\"mo\" id=\"MathJax-Span-16\">&lt;</span><span class=\"mi\" id=\"MathJax-Span-17\">n</span><span class=\"mo\" id=\"MathJax-Span-18\">,</span><span class=\"mi\" id=\"MathJax-Span-19\">k</span><span class=\"mo\" id=\"MathJax-Span-20\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-22\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-23\">5</span><span></span></span></span></span><span></span></span><span></span></span><span>) &mdash; длина массива и число запросов. Во второй строке содержатся&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-24\"><span><span class=\"mi\" id=\"MathJax-Span-26\">n</span><span></span></span><span></span></span><span>&nbsp;элементов массива, отсортированного по неубыванию. В третьей строке содержатся&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-27\"><span><span class=\"mi\" id=\"MathJax-Span-29\">k</span><span></span></span><span></span></span><span>&nbsp;запросов. Все элементы массива и запросы &mdash; целые числа, каждое из которых по модулю не превосходит&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-30\"><span><span class=\"mrow\" id=\"MathJax-Span-31\"><span class=\"mn\" id=\"MathJax-Span-32\">2</span><span class=\"mo\" id=\"MathJax-Span-33\">&sdot;</span><span><span><span class=\"mn\" id=\"MathJax-Span-35\">10^</span></span><span><span class=\"mn\" id=\"MathJax-Span-36\">9</span><span></span></span></span></span><span></span></span><span></span></span><span>&nbsp;.</span></p>', 1, 256, '<p><span>В первой строке входных данных содержатся числа&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-7\"><span><span class=\"mi\" id=\"MathJax-Span-9\">n</span><span></span></span><span></span></span><span>&nbsp;и&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-10\"><span><span class=\"mi\" id=\"MathJax-Span-12\">k</span><span></span></span><span></span></span><span>&nbsp;(</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-13\"><span><span class=\"mrow\" id=\"MathJax-Span-14\"><span class=\"mn\" id=\"MathJax-Span-15\">0</span><span class=\"mo\" id=\"MathJax-Span-16\">&lt;</span><span class=\"mi\" id=\"MathJax-Span-17\">n</span><span class=\"mo\" id=\"MathJax-Span-18\">,</span><span class=\"mi\" id=\"MathJax-Span-19\">k</span><span class=\"mo\" id=\"MathJax-Span-20\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-22\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-23\">5</span><span></span></span></span></span><span></span></span><span></span></span><span>) &mdash; длина массива и число запросов. Во второй строке содержатся&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-24\"><span><span class=\"mi\" id=\"MathJax-Span-26\">n</span><span></span></span><span></span></span><span>&nbsp;элементов массива, отсортированного по неубыванию. В третьей строке содержатся&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-27\"><span><span class=\"mi\" id=\"MathJax-Span-29\">k</span><span></span></span><span></span></span><span>&nbsp;запросов. Все элементы массива и запросы &mdash; целые числа, каждое из которых по модулю не превосходит&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-30\"><span><span class=\"mrow\" id=\"MathJax-Span-31\"><span class=\"mn\" id=\"MathJax-Span-32\">2</span><span class=\"mo\" id=\"MathJax-Span-33\">&sdot;</span><span><span class=\"mn\" id=\"MathJax-Span-35\">10^</span><span><span class=\"mn\" id=\"MathJax-Span-36\">9</span><span></span></span></span></span><span></span></span><span></span></span><span>&nbsp;.</span></p>', '<p><span>Для каждого из&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-37\"><span><span class=\"mi\" id=\"MathJax-Span-39\">k</span><span></span></span><span></span></span><span>&nbsp;запросов выведите максимальный индекс элемента массива, не большего данного. Если таких нет, выведите&nbsp;</span><span class=\"tex-font-style-tt\">0</span><span>.</span></p>', 50, 0, '2026-09-10 07:03:46', '2026-09-10 07:03:46', NULL, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(32, NULL, 'Ближайшее справа', '<div>\r\n<p>Дан массив из<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-1\"><span><span class=\"mi\" id=\"MathJax-Span-3\">n</span><span></span></span><span></span></span><span>&nbsp;</span>чисел, отсортированный по неубыванию, и<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-4\"><span><span class=\"mi\" id=\"MathJax-Span-6\">k</span><span></span></span><span></span></span><span>&nbsp;</span>запросов. Для каждого запроса выведите минимальный индекс элемента массива, не меньшего данного.</p>\r\n</div>', NULL, 1, 256, '<p><span>В первой строке входных данных содержатся числа&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-7\"><span><span class=\"mi\" id=\"MathJax-Span-9\">n</span><span></span></span><span></span></span><span>&nbsp;и&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-10\"><span><span class=\"mi\" id=\"MathJax-Span-12\">k</span><span></span></span><span></span></span><span>&nbsp;(</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-13\"><span><span class=\"mrow\" id=\"MathJax-Span-14\"><span class=\"mn\" id=\"MathJax-Span-15\">0</span><span class=\"mo\" id=\"MathJax-Span-16\">&lt;</span><span class=\"mi\" id=\"MathJax-Span-17\">n</span><span class=\"mo\" id=\"MathJax-Span-18\">,</span><span class=\"mi\" id=\"MathJax-Span-19\">k</span><span class=\"mo\" id=\"MathJax-Span-20\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-22\">10^</span></span><span><span class=\"mn\" id=\"MathJax-Span-23\">5</span><span></span></span></span></span><span></span></span><span></span></span><span>) &mdash; длина массива и число запросов. Во второй строке содержатся&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-24\"><span><span class=\"mi\" id=\"MathJax-Span-26\">n</span><span></span></span><span></span></span><span>&nbsp;элементов массива, отсортированного по неубыванию. В третьей строке содержатся&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-27\"><span><span class=\"mi\" id=\"MathJax-Span-29\">k</span><span></span></span><span></span></span><span>&nbsp;запросов. Все элементы массива и запросы &mdash; целые числа, каждое из которых по модулю не превосходит&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-30\"><span><span class=\"mrow\" id=\"MathJax-Span-31\"><span class=\"mn\" id=\"MathJax-Span-32\">2</span><span class=\"mo\" id=\"MathJax-Span-33\">&sdot;</span><span><span><span class=\"mn\" id=\"MathJax-Span-35\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-36\">9</span><span></span></span></span></span><span></span></span><span></span></span><span>&nbsp;.</span></p>', '<p><span>Для каждого из&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-37\"><span><span class=\"mi\" id=\"MathJax-Span-39\">k</span><span></span></span><span></span></span><span>&nbsp;запросов выведите минимальный индекс элемента массива, не меньшего данного. Если таких нет, выведите&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-40\"><span><span class=\"mrow\" id=\"MathJax-Span-41\"><span class=\"mi\" id=\"MathJax-Span-42\">n</span><span class=\"mo\" id=\"MathJax-Span-43\">+</span><span class=\"mn\" id=\"MathJax-Span-44\">1</span></span><span></span></span><span></span></span><span>.</span></p>', 50, 0, '2026-09-10 07:08:10', '2026-09-10 07:08:10', NULL, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(33, NULL, 'Быстрый поиск в массиве', '<p>Дан массив<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-1\"><span><span class=\"mi\" id=\"MathJax-Span-3\">a</span><span></span></span><span></span></span><span>&nbsp;</span>из<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-4\"><span><span class=\"mi\" id=\"MathJax-Span-6\">n</span><span></span></span><span></span></span><span>&nbsp;</span>целых чисел<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-7\"><span><span class=\"mrow\" id=\"MathJax-Span-8\"><span><span><span class=\"mi\" id=\"MathJax-Span-10\">a</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-11\">1</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-12\">,</span><span><span><span class=\"mi\" id=\"MathJax-Span-14\">a</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-15\">2</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-16\">,</span><span class=\"mo\" id=\"MathJax-Span-17\">&hellip;</span><span class=\"mo\" id=\"MathJax-Span-18\">,</span><span><span><span class=\"mi\" id=\"MathJax-Span-20\">a</span><span></span></span><span><span class=\"mi\" id=\"MathJax-Span-21\">n</span><span></span></span></span></span><span></span></span><span></span></span>.</p>\r\n<p>Нужно уметь отвечать на запросы вида &laquo;Сколько чисел имеют значения от<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-22\"><span><span class=\"mi\" id=\"MathJax-Span-24\">l</span><span></span></span><span></span></span><span>&nbsp;</span>до<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-25\"><span><span class=\"mi\" id=\"MathJax-Span-27\">r</span><span></span></span><span></span></span>&raquo;?</p>', NULL, 1, 256, '<p>В первой строке находится целое число<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-28\"><span><span class=\"mi\" id=\"MathJax-Span-30\">n</span><span></span></span><span></span></span><span>&nbsp;</span>(<span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-31\"><span><span class=\"mrow\" id=\"MathJax-Span-32\"><span class=\"mn\" id=\"MathJax-Span-33\">1</span><span class=\"mo\" id=\"MathJax-Span-34\">&le;</span><span class=\"mi\" id=\"MathJax-Span-35\">n</span><span class=\"mo\" id=\"MathJax-Span-36\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-38\">10^</span></span><span><span class=\"mn\" id=\"MathJax-Span-39\">5</span><span></span></span></span></span><span></span></span><span></span></span>)&nbsp;&mdash; длина массива.</p>\r\n<p>Во второй строке находятся<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-40\"><span><span class=\"mi\" id=\"MathJax-Span-42\">n</span><span></span></span><span></span></span><span>&nbsp;</span>целых чисел<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-43\"><span><span class=\"mrow\" id=\"MathJax-Span-44\"><span><span><span class=\"mi\" id=\"MathJax-Span-46\">a</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-47\">1</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-48\">,</span><span><span><span class=\"mi\" id=\"MathJax-Span-50\">a</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-51\">2</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-52\">,</span><span class=\"mo\" id=\"MathJax-Span-53\">&hellip;</span><span class=\"mo\" id=\"MathJax-Span-54\">,</span><span><span><span class=\"mi\" id=\"MathJax-Span-56\">a</span><span></span></span><span><span class=\"mi\" id=\"MathJax-Span-57\">n</span><span></span></span></span></span><span></span></span><span></span></span><span>&nbsp;</span>(<span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-58\"><span><span class=\"mrow\" id=\"MathJax-Span-59\"><span class=\"mo\" id=\"MathJax-Span-60\">&minus;</span><span><span><span class=\"mn\" id=\"MathJax-Span-62\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-63\">9</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-64\">&le;</span><span><span><span class=\"mi\" id=\"MathJax-Span-66\">a</span><span></span></span><span><span class=\"mi\" id=\"MathJax-Span-67\">i</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-68\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-70\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-71\">9</span><span></span></span></span></span><span></span></span><span></span></span>).</p>\r\n<p>В третьей строке находится целое число<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-72\"><span><span class=\"mi\" id=\"MathJax-Span-74\">k</span><span></span></span><span></span></span><span>&nbsp;</span>(<span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-75\"><span><span class=\"mrow\" id=\"MathJax-Span-76\"><span class=\"mn\" id=\"MathJax-Span-77\">1</span><span class=\"mo\" id=\"MathJax-Span-78\">&le;</span><span class=\"mi\" id=\"MathJax-Span-79\">k</span><span class=\"mo\" id=\"MathJax-Span-80\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-82\">10^</span></span><span><span class=\"mn\" id=\"MathJax-Span-83\">5</span><span></span></span></span></span><span></span></span><span></span></span>)&nbsp;&mdash; число запросов.</p>\r\n<p>В следующих<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-84\"><span><span class=\"mi\" id=\"MathJax-Span-86\">k</span><span></span></span><span></span></span><span>&nbsp;</span>строках находятся пары чисел<span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-87\"><span><span class=\"mi\" id=\"MathJax-Span-89\">l</span><span></span></span><span></span></span><span>&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-90\"><span><span class=\"mi\" id=\"MathJax-Span-92\">r</span><span></span></span><span></span></span><span>&nbsp;</span>(<span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-93\"><span><span class=\"mrow\" id=\"MathJax-Span-94\"><span class=\"mo\" id=\"MathJax-Span-95\">&minus;</span><span><span><span class=\"mn\" id=\"MathJax-Span-97\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-98\">9</span><span></span></span></span><span class=\"mo\" id=\"MathJax-Span-99\">&le;</span><span class=\"mi\" id=\"MathJax-Span-100\">l</span><span class=\"mo\" id=\"MathJax-Span-101\">&le;</span><span class=\"mi\" id=\"MathJax-Span-102\">r</span><span class=\"mo\" id=\"MathJax-Span-103\">&le;</span><span><span><span class=\"mn\" id=\"MathJax-Span-105\">10^</span><span></span></span><span><span class=\"mn\" id=\"MathJax-Span-106\">9</span><span></span></span></span></span><span></span></span><span></span></span>).</p>', '<p><span>Выведите&nbsp;</span><span class=\"MathJax_Preview\"></span><span class=\"math\" id=\"MathJax-Span-107\"><span><span class=\"mi\" id=\"MathJax-Span-109\">k</span><span></span></span><span></span></span><span>&nbsp;чисел&nbsp;&mdash; ответы на запросы.</span></p>', 50, 0, '2026-09-10 07:13:06', '2026-09-10 07:13:06', NULL, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(34, NULL, 'Упаковка прямоугольников', '<p>Даны n прямоугольников одинакового размера: w в ширину и h в длину. Требуется найти квадрат минимального размера, в который можно упаковать все данные прямоугольники.</p>\r\n<p>Прямоугольники нельзя поворачивать.</p>\r\n<p><img class=\"tex-graphics\" src=\"https://espresso.codeforces.com/848cbd12b2d10d145d552a6cbb35f3bd244b8bed.png\"></p>', NULL, 1, 256, '<p>Ввод содержит три целых числа: w, h, n (1 &le; w, h, n &le; 10^9).</p>', '<p>Выведите минимальную длину стороны квадрата, в который можно упаковать все заданные прямоугольники.</p>', 50, 0, '2026-09-10 08:44:57', '2026-09-10 13:39:18', 11, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(35, NULL, 'Очень Легкая Задача', '<p class=\"isSelectedEnd\"><span>Сегодня утром жюри решило добавить в вариант олимпиады еще одну, Очень Легкую Задачу. Ответственный секретарь Оргкомитета напечатал ее условие в одном экземпляре, и теперь ему нужно до начала олимпиады успеть сделать еще n копий.</span></p>\r\n<p class=\"isSelectedEnd\"><span>В его распоряжении имеются два ксерокса, один из которых копирует лист за x секунд, а другой &mdash; за y секунд.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Разрешается использовать как один ксерокс, так и оба одновременно. Можно копировать не только с оригинала, но и с копии.</span></p>\r\n<p><span>Помогите ему выяснить, какое минимальное время потребуется, чтобы сделать n копий условия задачи.</span></p>', NULL, 1, 256, '<p class=\"isSelectedEnd\"><span>На вход программы поступают три натуральных числа n, x и y, разделенные пробелом.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Ограничения:</span><br><span>1 &le; n &le; 2 &middot; 10^8</span><br><span>1 &le; x, y &le; 10</span></p>', '<p>Выведите одно число &mdash; минимальное время в секундах, необходимое для получения n копий.</p>', 50, 0, '2026-09-10 08:47:30', '2026-09-10 14:40:31', 11, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(36, NULL, 'Веревочки', '<p class=\"isSelectedEnd\"><span>Есть n веревочек. Из них нужно нарезать k кусков одинаковой целой длины. Найдите максимальную длину кусков, которые можно получить.</span></p>\r\n<p><span>Каждый кусок должен иметь целую длину. Оставшиеся части веревочек можно не использовать.</span></p>', NULL, 1, 256, '<p class=\"isSelectedEnd\"><span>В первой строке заданы два числа &mdash; n и k (1 &le; n, k &le; 10000).</span></p>\r\n<p><span>Далее в каждой из последующих n строк записано по одному числу &mdash; длина очередной веревочки ai (1 &le; ai &le; 10^7).</span></p>', '<p>Выведите одно целое число &mdash; максимальную длину кусков, которые можно получить.</p>', 50, 0, '2026-09-10 08:51:44', '2026-09-10 14:40:42', 11, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(37, NULL, 'Игра со строкой', '<p class=\"isSelectedEnd\"><span>У Пети есть слово t, он хочет, чтобы из него получилось слово p.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Петя начинает вычеркивать буквы в некотором порядке, который задан перестановкой номеров букв слова t: a1, a2, ..., a|t|.</span></p>\r\n<p class=\"isSelectedEnd\"><span>После вычеркивания буквы нумерация остальных букв не меняется.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Его брат Вася боится, что Петя может удалить слишком много букв, и слово p не получится. Задача Васи состоит в том, чтобы в некоторый момент времени остановить брата и закончить вычеркивание самому, получив после этого слово p.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Так как Пете нравится это занятие, Вася хочет остановить его как можно позже.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Ваша задача &mdash; определить, сколько букв может вычеркнуть Петя до того, как его остановит Вася.</span></p>\r\n<p><span>Гарантируется, что слово p можно получить вычеркиванием некоторых букв из t.</span></p>', NULL, 1, 256, '<p class=\"isSelectedEnd\"><span>Первая и вторая строки входного файла содержат слова t и p соответственно.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Слова состоят из строчных букв латинского алфавита.</span></p>\r\n<p class=\"isSelectedEnd\"><span>Ограничения:</span><br><span>1 &le; |p| &lt; |t| &le; 200000</span></p>\r\n<p class=\"isSelectedEnd\"><span>Следующая строка содержит перестановку a1, a2, ..., a|t| номеров букв, задающую порядок, в котором Петя вычеркивает буквы слова t.</span></p>\r\n<p><span>Ограничения:</span><br><span>1 &le; ai &le; |t|, все ai различны.</span></p>', '<p>Выведите одно число &mdash; максимальное количество букв, которые может вычеркнуть Петя.</p>', 15, 0, '2026-09-10 09:02:56', '2026-09-30 04:03:29', 11, 'easy', NULL, 1, NULL, NULL, NULL, 0);
INSERT INTO `problems` (`id`, `contest_id`, `title`, `statement`, `notes`, `time_limit`, `memory_limit`, `input`, `output`, `score`, `order_index`, `created_at`, `updated_at`, `skill_id`, `complexity`, `solution_source`, `solution_language_id`, `tests_status`, `tests_log`, `tests_generated_at`, `hidden_from_archive`) VALUES
(38, NULL, 'Дороги в Таджикистане', '<p>В Таджикистане есть N городов, некоторые из которых соединены дорогами. Руководство страны решило провести инвентаризацию дорог. Но, как оказалось, ответственные специалисты не сильны в математике, поэтому они просят вас сосчитать количество дорог. Требуется написать программу, помогающую определить количество дорог в Таджикистане.</p>\r\n<p><strong>Входные данные</strong></p>\r\n<p>В первой строке входного файла INPUT.TXT записано число N (0 &le; N &le; 100). В следующих N строках записано по N чисел, каждое из которых является единичкой или ноликом. Причем, если в позиции (i, j) квадратной матрицы стоит единичка, то i-ый и j-ый города соединены дорогами, а если нолик, то не соединены. Гарантируется, что все дороги соединяют различные города.</p>\r\n<p><strong>Выходные данные</strong></p>\r\n<p>В выходной файл OUTPUT.TXT необходимо вывести число, определяющее количество дорог в Таджикистане.</p>\r\n<div id=\"rmWrap\" style=\"max-width: 720px; margin: 0 auto; padding: 16px; box-sizing: border-box; font-family: Arial,Helvetica,sans-serif; line-height: 1.6; color: #2c2c2a;\"><svg id=\"rmSvg\" viewBox=\"0 0 680 290\" width=\"100%\" style=\"display: block; height: auto;\" xmlns=\"http://www.w3.org/2000/svg\">\r\n<g id=\"rmMatrix\"></g>\r\n<line x1=\"60\" y1=\"80\" x2=\"230\" y2=\"250\" stroke=\"#9c9a92\" stroke-width=\"1\" stroke-dasharray=\"4 3\"></line>\r\n<g id=\"rmEdges\"></g>\r\n<g id=\"rmNodes\"></g>\r\n</svg>\r\n<div style=\"margin-top: 14px;\"><span style=\"display: inline-block; background: #f1efe8; border-radius: 8px; padding: 10px 16px; margin-right: 10px;\"> <span style=\"font-size: 13px; color: #73726c;\">Дорог:</span> <span id=\"rmCnt\" style=\"font-size: 22px; font-weight: 500; margin-left: 8px; color: #2c2c2a;\">0</span> </span> <button id=\"rmB0\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 14px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 8px 14px; margin-right: 6px; cursor: pointer;\">Очистить</button> <button id=\"rmB1\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 14px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 8px 14px; margin-right: 6px; cursor: pointer;\">Пример из условия</button> <button id=\"rmB2\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 14px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 8px 14px; cursor: pointer;\">Полный граф</button></div>\r\n<p style=\"font-size: 14px; color: #73726c; margin: 14px 0 0;\">Клик по клетке вне диагонали добавляет или убирает дорогу. Меняются сразу две клетки &mdash; матрица симметрична. Счётчик считает только клетки выше диагонали.</p>\r\n<pre id=\"rmOut\" style=\"font-family: Consolas,Monaco,monospace; font-size: 13px; background: #f1efe8; border-radius: 8px; padding: 12px; margin-top: 12px; overflow-x: auto; color: #2c2c2a;\"></pre>\r\n</div>\r\n<p>\r\n<script>\r\n(function(){\r\nfunction boot(){\r\nvar root=document.getElementById(\"rmWrap\");\r\nif(!root||root.getAttribute(\"data-ready\")===\"1\")return;\r\nroot.setAttribute(\"data-ready\",\"1\");\r\n\r\nvar NS=\"http://www.w3.org/2000/svg\";\r\nvar N=5,S=34,X0=60,Y0=80;\r\nvar NP=[[480,70],[570,136],[536,242],[424,242],[390,136]];\r\nvar CB=\"#f1efe8\",CS=\"#d3d1c7\",CF=\"#e1f5ee\",CK=\"#1d9e75\",CT=\"#2c2c2a\",CM=\"#73726c\";\r\nvar E=[],i,j;\r\nfor(i=0;i<N;i++)E.push([0,0,0,0,0]);\r\n\r\nvar mg=document.getElementById(\"rmMatrix\");\r\nvar eg=document.getElementById(\"rmEdges\");\r\nvar ng=document.getElementById(\"rmNodes\");\r\nvar out=document.getElementById(\"rmOut\");\r\nvar cnt=document.getElementById(\"rmCnt\");\r\n\r\nfunction el(t,a){var e=document.createElementNS(NS,t);for(var k in a)e.setAttribute(k,a[k]);return e;}\r\n\r\nfor(j=0;j<N;j++){\r\nvar h=el(\"text\",{x:X0+S*j+S/2,y:68,\"text-anchor\":\"middle\",\"font-size\":\"12\",\"font-family\":\"Arial,Helvetica,sans-serif\",fill:CM});\r\nh.appendChild(document.createTextNode(j+1));mg.appendChild(h);\r\nvar v=el(\"text\",{x:46,y:Y0+S*j+S/2+4,\"text-anchor\":\"middle\",\"font-size\":\"12\",\"font-family\":\"Arial,Helvetica,sans-serif\",fill:CM});\r\nv.appendChild(document.createTextNode(j+1));mg.appendChild(v);\r\n}\r\n\r\nvar cells=[],nums=[];\r\nfor(i=0;i<N;i++){\r\ncells.push([]);nums.push([]);\r\nfor(j=0;j<N;j++){\r\nvar r=el(\"rect\",{x:X0+S*j,y:Y0+S*i,width:S,height:S,fill:CB,stroke:CS,\"stroke-width\":\"0.5\"});\r\nif(i!==j){\r\nr.style.cursor=\"pointer\";\r\n(function(a,b,rr){\r\nrr.addEventListener(\"click\",function(){tog(a,b);});\r\nrr.addEventListener(\"mouseover\",function(){rr.setAttribute(\"stroke\",CK);rr.setAttribute(\"stroke-width\",\"1.5\");});\r\nrr.addEventListener(\"mouseout\",function(){rr.setAttribute(\"stroke\",E[a][b]?CK:CS);rr.setAttribute(\"stroke-width\",\"0.5\");});\r\n})(i,j,r);\r\n}\r\nmg.appendChild(r);cells[i].push(r);\r\nvar t=el(\"text\",{x:X0+S*j+S/2,y:Y0+S*i+S/2+5,\"text-anchor\":\"middle\",\"font-size\":\"14\",\"font-family\":\"Arial,Helvetica,sans-serif\",fill:CT,\"pointer-events\":\"none\"});\r\nt.appendChild(document.createTextNode(\"0\"));mg.appendChild(t);nums[i].push(t);\r\n}\r\n}\r\n\r\nvar lines={};\r\nfor(i=0;i<N;i++)for(j=i+1;j<N;j++){\r\nvar L=el(\"line\",{x1:NP[i][0],y1:NP[i][1],x2:NP[j][0],y2:NP[j][1],stroke:CK,\"stroke-width\":\"2\",\"stroke-opacity\":\"0\"});\r\neg.appendChild(L);lines[i+\"-\"+j]=L;\r\n}\r\n\r\nvar circ=[];\r\nfor(i=0;i<N;i++){\r\nvar c=el(\"circle\",{cx:NP[i][0],cy:NP[i][1],r:22,fill:CB,stroke:CS,\"stroke-width\":\"0.5\"});\r\nng.appendChild(c);circ.push(c);\r\nvar nt=el(\"text\",{x:NP[i][0],y:NP[i][1]+5,\"text-anchor\":\"middle\",\"font-size\":\"14\",\"font-weight\":\"bold\",\"font-family\":\"Arial,Helvetica,sans-serif\",fill:CT});\r\nnt.appendChild(document.createTextNode(i+1));ng.appendChild(nt);\r\n}\r\n\r\nfunction rend(){\r\nvar n=0,a,b,txt=N+\"\\n\";\r\nfor(a=0;a<N;a++){\r\nvar row=[];\r\nfor(b=0;b<N;b++){\r\nrow.push(E[a][b]);\r\nnums[a][b].firstChild.nodeValue=E[a][b];\r\ncells[a][b].setAttribute(\"fill\",E[a][b]?CF:CB);\r\ncells[a][b].setAttribute(\"stroke\",E[a][b]?CK:CS);\r\ncells[a][b].setAttribute(\"stroke-width\",\"0.5\");\r\nif(b>a&&E[a][b])n++;\r\n}\r\ntxt+=row.join(\" \")+\"\\n\";\r\n}\r\nfor(a=0;a<N;a++)for(b=a+1;b<N;b++)lines[a+\"-\"+b].setAttribute(\"stroke-opacity\",E[a][b]?\"1\":\"0\");\r\nfor(a=0;a<N;a++){\r\nvar d=0;\r\nfor(b=0;b<N;b++)d+=E[a][b];\r\ncirc[a].setAttribute(\"fill\",d?CF:CB);\r\ncirc[a].setAttribute(\"stroke\",d?CK:CS);\r\n}\r\ncnt.firstChild.nodeValue=n;\r\nout.firstChild.nodeValue=\"INPUT.TXT\\n\"+txt+\"\\nOUTPUT.TXT\\n\"+n;\r\n}\r\n\r\nfunction tog(a,b){E[a][b]=E[a][b]?0:1;E[b][a]=E[a][b];rend();}\r\n\r\nfunction pre(k){\r\nvar a,b;\r\nfor(a=0;a<N;a++)for(b=0;b<N;b++)E[a][b]=0;\r\nif(k===1){E[0][1]=E[1][0]=1;E[1][2]=E[2][1]=1;E[1][3]=E[3][1]=1;}\r\nif(k===2){for(a=0;a<N;a++)for(b=0;b<N;b++)if(a!==b)E[a][b]=1;}\r\nrend();\r\n}\r\n\r\nif(!out.firstChild)out.appendChild(document.createTextNode(\"\"));\r\nif(!cnt.firstChild)cnt.appendChild(document.createTextNode(\"0\"));\r\n\r\ndocument.getElementById(\"rmB0\").addEventListener(\"click\",function(){pre(0);});\r\ndocument.getElementById(\"rmB1\").addEventListener(\"click\",function(){pre(1);});\r\ndocument.getElementById(\"rmB2\").addEventListener(\"click\",function(){pre(2);});\r\n\r\npre(1);\r\n}\r\nif(document.readyState===\"loading\"){document.addEventListener(\"DOMContentLoaded\",boot);}else{boot();}\r\n})();\r\n</script>\r\n</p>', NULL, 1, 256, '<p>5<br>0 1 0 0 0<br>1 0 1 1 0<br>0 1 0 0 0<br>0 1 0 0 0<br>0 0 0 0 0</p>', '<p>3</p>', 100, 0, '2026-09-24 03:22:23', '2026-09-24 06:19:34', 1, 'easy', 'import sys\r\n\r\ndef solve():\r\n    # Читаем N\r\n    try:\r\n        line = sys.stdin.readline()\r\n        if not line:\r\n            return\r\n        n = int(line.strip())\r\n    except ValueError:\r\n        return\r\n\r\n    total_roads = 0\r\n    \r\n    # Читаем строки матрицы\r\n    for _ in range(n):\r\n        row = map(int, sys.stdin.readline().split())\r\n        total_roads += sum(row)\r\n    \r\n    # Каждая дорога в матрице смежности учтена дважды (i,j) и (j,i)\r\n    print(total_roads // 2)\r\n\r\nif __name__ == \"__main__\":\r\n    solve()', 2, 'ready', 'Тестов всего: 51.\nОтветов посчитано эталоном: 0.\nРучных ответов проверено и подтверждено: 51.', '2026-09-24 06:19:34', 0),
(39, NULL, 'Заповедники', '<p dir=\"ltr\">В Гиссарской долине расположены N природных заповедников, имеющих форму прямоугольников. Среди них &mdash; участки, где охраняют бухарского оленя, винторогого козла-мархура и тугайные леса вдоль Вахша.</p>\r\n<p dir=\"ltr\">На совете хукумата области было принято решение расширить охраняемые территории. Директор каждого заповедника выбрал Ri &mdash; количество метров, на которое отодвигается граница его заповедника во все стороны.</p>\r\n<p dir=\"ltr\">Однако после подписания соглашения выяснилось, что некоторые заповедники стали иметь общие земли. Такие заповедники решено объединить в один. Если объединённый заповедник снова пересекается с каким-нибудь другим, их опять объединяют, и так до тех пор, пока не останутся заповедники, не имеющие общих земель.</p>\r\n<p dir=\"ltr\">Ваша задача &mdash; посчитать, сколько заповедников стало в долине после объединения.</p>\r\n<div id=\"zpWrap\" style=\"max-width: 720px; margin: 0 auto; padding: 16px; box-sizing: border-box; font-family: Arial,Helvetica,sans-serif; line-height: 1.6; color: #2c2c2a;\"><svg id=\"zpSvg\" viewBox=\"0 0 680 440\" width=\"100%\" style=\"display: block; height: auto;\" xmlns=\"http://www.w3.org/2000/svg\">\r\n<g id=\"zpGrid\"></g>\r\n<g id=\"zpGrown\"></g>\r\n<g id=\"zpBase\"></g>\r\n<g id=\"zpLab\"></g>\r\n</svg>\r\n<div style=\"margin-top: 14px;\"><span style=\"font-size: 14px; color: #73726c;\">R (метров):</span> <input id=\"zpR\" type=\"range\" min=\"0\" max=\"40\" value=\"0\" step=\"1\" style=\"vertical-align: middle; width: 260px; margin: 0 10px;\"> <span id=\"zpRv\" style=\"font-size: 20px; font-weight: bold; color: #2c2c2a; display: inline-block; min-width: 32px;\">0</span> <button id=\"zpM\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 16px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 4px 12px; margin-left: 6px; cursor: pointer;\">&minus;</button> <button id=\"zpP\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 16px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 4px 12px; cursor: pointer;\">+</button></div>\r\n<div style=\"margin-top: 12px;\"><span style=\"display: inline-block; background: #f1efe8; border-radius: 8px; padding: 10px 16px; margin-right: 10px;\"> <span style=\"font-size: 13px; color: #73726c;\">Заповедников осталось:</span> <span id=\"zpCnt\" style=\"font-size: 22px; font-weight: bold; margin-left: 8px; color: #2c2c2a;\">7</span> </span> <button id=\"zpB1\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 14px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 8px 14px; margin-right: 6px; cursor: pointer;\">Исходная долина</button> <button id=\"zpB2\" type=\"button\" style=\"font-family: Arial,Helvetica,sans-serif; font-size: 14px; color: #2c2c2a; background: #fff; border: 1px solid #d3d1c7; border-radius: 8px; padding: 8px 14px; cursor: pointer;\">Случайное расположение</button></div>\r\n<p style=\"font-size: 14px; color: #73726c; margin: 14px 0 0;\">Сплошные прямоугольники &mdash; исходные заповедники, пунктирные &mdash; после расширения на R метров. Одинаковый цвет означает, что участки уже объединены в один заповедник. Двигайте ползунок и следите за счётчиком.</p>\r\n</div>\r\n<p>\r\n<script>\r\n(function(){\r\nfunction boot(){\r\nvar root=document.getElementById(\"zpWrap\");\r\nif(!root||root.getAttribute(\"data-ready\")===\"1\")return;\r\nroot.setAttribute(\"data-ready\",\"1\");\r\n\r\nvar NS=\"http://www.w3.org/2000/svg\";\r\nvar SC=6, OX=340, OY=220;\r\nvar PAL=[\"#1d9e75\",\"#c96442\",\"#3b7ea1\",\"#a06fc4\",\"#c9a227\",\"#5a8f3d\",\"#b45f8a\",\"#4d7c6f\"];\r\nvar CS=\"#d3d1c7\", CM=\"#9c9a92\", CT=\"#2c2c2a\";\r\n\r\nvar BASE=[\r\n[-40,10,-25,25],[-18,14,-5,24],[5,12,20,26],[25,8,38,20],\r\n[-35,-25,-20,-10],[-5,-28,10,-12],[22,-26,36,-12]\r\n];\r\nvar R=[], RC=[];\r\nvar gg=document.getElementById(\"zpGrown\");\r\nvar bg=document.getElementById(\"zpBase\");\r\nvar lg=document.getElementById(\"zpLab\");\r\nvar grid=document.getElementById(\"zpGrid\");\r\nvar cnt=document.getElementById(\"zpCnt\");\r\nvar sl=document.getElementById(\"zpR\");\r\nvar rv=document.getElementById(\"zpRv\");\r\n\r\nfunction el(t,a){var e=document.createElementNS(NS,t);for(var k in a)e.setAttribute(k,a[k]);return e;}\r\nfunction px(x){return OX+x*SC;}\r\nfunction py(y){return OY-y*SC;}\r\n\r\nvar i;\r\nfor(i=-50;i<=50;i+=10)grid.appendChild(el(\"line\",{x1:px(i),y1:py(35),x2:px(i),y2:py(-35),stroke:\"#e8e6df\",\"stroke-width\":\"1\"}));\r\nfor(i=-30;i<=30;i+=10)grid.appendChild(el(\"line\",{x1:px(-50),y1:py(i),x2:px(50),y2:py(i),stroke:\"#e8e6df\",\"stroke-width\":\"1\"}));\r\ngrid.appendChild(el(\"line\",{x1:px(-50),y1:py(0),x2:px(50),y2:py(0),stroke:CS,\"stroke-width\":\"1\"}));\r\ngrid.appendChild(el(\"line\",{x1:px(0),y1:py(35),x2:px(0),y2:py(-35),stroke:CS,\"stroke-width\":\"1\"}));\r\n\r\nfunction mk(){\r\nwhile(gg.firstChild)gg.removeChild(gg.firstChild);\r\nwhile(bg.firstChild)bg.removeChild(bg.firstChild);\r\nwhile(lg.firstChild)lg.removeChild(lg.firstChild);\r\nRC=[];\r\nfor(var k=0;k<R.length;k++){\r\nRC.push({g:el(\"rect\",{fill:\"none\",stroke:CM,\"stroke-width\":\"1.5\",\"stroke-dasharray\":\"5 4\",\"fill-opacity\":\"0.14\"}),\r\nb:el(\"rect\",{stroke:CM,\"stroke-width\":\"1.5\",\"fill-opacity\":\"0.42\"}),\r\nt:el(\"text\",{\"text-anchor\":\"middle\",\"font-size\":\"13\",\"font-weight\":\"bold\",\"font-family\":\"Arial,Helvetica,sans-serif\",fill:CT})});\r\nRC[k].t.appendChild(document.createTextNode(String(k+1)));\r\ngg.appendChild(RC[k].g);bg.appendChild(RC[k].b);lg.appendChild(RC[k].t);\r\n}\r\n}\r\n\r\nfunction find(p,a){while(p[a]!==a)a=p[a];return a;}\r\n\r\nfunction rend(){\r\nvar r=+sl.value,n=R.length,k,j;\r\nrv.firstChild.nodeValue=r;\r\nvar ex=[];\r\nfor(k=0;k<n;k++)ex.push([R[k][0]-r,R[k][1]-r,R[k][2]+r,R[k][3]+r]);\r\nvar p=[];\r\nfor(k=0;k<n;k++)p.push(k);\r\nfor(k=0;k<n;k++)for(j=k+1;j<n;j++){\r\nif(Math.max(ex[k][0],ex[j][0])<=Math.min(ex[k][2],ex[j][2])&&\r\n   Math.max(ex[k][1],ex[j][1])<=Math.min(ex[k][3],ex[j][3])){\r\nvar a=find(p,k),b=find(p,j);if(a!==b)p[a]=b;\r\n}}\r\nvar col={},nc=0;\r\nfor(k=0;k<n;k++){var f=find(p,k);if(col[f]===undefined)col[f]=nc++;}\r\nfor(k=0;k<n;k++){\r\nvar c=PAL[col[find(p,k)]%PAL.length];\r\nRC[k].g.setAttribute(\"x\",px(ex[k][0]));RC[k].g.setAttribute(\"y\",py(ex[k][3]));\r\nRC[k].g.setAttribute(\"width\",(ex[k][2]-ex[k][0])*SC);RC[k].g.setAttribute(\"height\",(ex[k][3]-ex[k][1])*SC);\r\nRC[k].g.setAttribute(\"stroke\",c);RC[k].g.setAttribute(\"fill\",c);\r\nRC[k].b.setAttribute(\"x\",px(R[k][0]));RC[k].b.setAttribute(\"y\",py(R[k][3]));\r\nRC[k].b.setAttribute(\"width\",(R[k][2]-R[k][0])*SC);RC[k].b.setAttribute(\"height\",(R[k][3]-R[k][1])*SC);\r\nRC[k].b.setAttribute(\"stroke\",c);RC[k].b.setAttribute(\"fill\",c);\r\nRC[k].t.setAttribute(\"x\",px((R[k][0]+R[k][2])/2));RC[k].t.setAttribute(\"y\",py((R[k][1]+R[k][3])/2)+5);\r\n}\r\ncnt.firstChild.nodeValue=nc;\r\n}\r\n\r\nfunction setup(rects){R=rects;mk();rend();}\r\nfunction reset1(){var a=[],k;for(k=0;k<BASE.length;k++)a.push(BASE[k].slice());setup(a);}\r\nfunction reset2(){\r\nvar a=[],k;\r\nfor(k=0;k<7;k++){\r\nvar w=4+Math.floor(Math.random()*14),h=4+Math.floor(Math.random()*12);\r\nvar x=-46+Math.floor(Math.random()*(92-w)),y=-30+Math.floor(Math.random()*(60-h));\r\na.push([x,y,x+w,y+h]);\r\n}\r\nsetup(a);\r\n}\r\n\r\nif(!rv.firstChild)rv.appendChild(document.createTextNode(\"0\"));\r\nif(!cnt.firstChild)cnt.appendChild(document.createTextNode(\"0\"));\r\n\r\nsl.addEventListener(\"input\",rend);\r\nsl.addEventListener(\"change\",rend);\r\ndocument.getElementById(\"zpM\").addEventListener(\"click\",function(){sl.value=Math.max(0,+sl.value-1);rend();});\r\ndocument.getElementById(\"zpP\").addEventListener(\"click\",function(){sl.value=Math.min(40,+sl.value+1);rend();});\r\ndocument.getElementById(\"zpB1\").addEventListener(\"click\",function(){sl.value=0;reset1();});\r\ndocument.getElementById(\"zpB2\").addEventListener(\"click\",function(){sl.value=0;reset2();});\r\n\r\nreset1();\r\n}\r\nif(document.readyState===\"loading\"){document.addEventListener(\"DOMContentLoaded\",boot);}else{boot();}\r\n})();\r\n</script>\r\n</p>', NULL, 1, 256, '<p>Первая строка входного файла INPUT.TXT содержит число N (1 &le; N &le; 100) &mdash; количество заповедников. Далее идут N строк, содержащих по пять целых чисел x1, y1, x2, y2, R. Пары (x1, y1) и (x2, y2) &mdash; координаты противоположных вершин заповедника в метрах (&minus;10⁴ &le; x1, y1, x2, y2 &le; 10⁴). Стороны заповедников параллельны осям координат. Заповедники, имеющие общую границу, считаются пересекающимися. R (0 &le; R &le; 10⁴) &mdash; расстояние, на которое отодвигается граница заповедника.</p>', '<p>В выходной файл OUTPUT.TXT выведите одно натуральное число &mdash; количество оставшихся заповедников после объединения.</p>', 100, 0, '2026-09-24 06:06:12', '2026-09-24 06:18:14', 1, 'easy', NULL, 1, NULL, NULL, NULL, 0),
(40, NULL, 'Begin1', '<p>Дана сторона квадрата a. Найти его периметр P = 4&middot;a.</p>', NULL, 1, 256, '<p>15</p>', '<p>60</p>', 50, 0, '2026-09-28 09:07:13', '2026-09-28 09:08:56', NULL, 'easy', '#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n  double a,p;\r\n  cin>>a;\r\n  p=4*a;\r\n  cout<<p;\r\n    return 0;\r\n}', 1, 'ready', 'Тестов всего: 1.\nОтветов посчитано эталоном: 1.', '2026-09-28 09:08:56', 0),
(41, NULL, 'Begin2', '<p>Дана сторона квадрата a. Найти его площадь S = a<sup>2</sup>.</p>', NULL, 1, 256, '<p>5</p>', '<p>25</p>', 50, 0, '2026-09-28 09:19:06', '2026-09-28 09:19:06', NULL, 'easy', '#include <iostream>\r\n\r\nusing namespace std;\r\n\r\nint main()\r\n{\r\n  double a,s;\r\n  cin>>a;\r\n  s=a*a;\r\n  cout<<s;\r\n    return 0;\r\n}', 1, 'ready', 'Тестов всего: 1.\nОтветов посчитано эталоном: 0.\nРучных ответов проверено и подтверждено: 1.', '2026-09-28 09:19:06', 0),
(42, NULL, 'Begin1', 'Дана сторона квадрата a. Найти его периметр P = 4·a.', NULL, 1, 256, 'Одно вещественное число: a.', 'Одно вещественное число (P), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\na = float(input())\nprint(f\"{4*a:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(43, NULL, 'Begin2', 'Дана сторона квадрата a. Найти его площадь S = a^2.', NULL, 1, 256, 'Одно вещественное число: a.', 'Одно вещественное число (S), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\na = float(input())\nprint(f\"{a**2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(44, NULL, 'Begin3', 'Даны стороны прямоугольника a и b. Найти его площадь S = a·b и периметр P = 2·(a + b).', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: a, b (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: S, P.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b = data\nprint(f\"{a*b:.2f}\")\nprint(f\"{2*(a+b):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(45, NULL, 'Begin4', 'Дан диаметр окружности d. Найти ее длину L = π·d. В качестве значения π использовать 3.14.', NULL, 1, 256, 'Одно вещественное число: d.', 'Одно вещественное число (L), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nd = float(input())\nprint(f\"{3.14*d:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(46, NULL, 'Begin5', 'Дана длина ребра куба a. Найти объем куба V = a^3 и площадь его поверхности S = 6·a^2.', NULL, 1, 256, 'Одно вещественное число: a.', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: V, S.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\na = float(input())\nprint(f\"{a**3:.2f}\")\nprint(f\"{6*a**2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(47, NULL, 'Begin6', 'Даны длины ребер a, b, c прямоугольного параллелепипеда. Найти его объем V = a·b·c и площадь поверхности S = 2·(a·b + b·c + a·c).', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: a, b, c (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: V, S.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b, c = data\nprint(f\"{a*b*c:.2f}\")\nprint(f\"{2*(a*b+b*c+a*c):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(48, NULL, 'Begin7', 'Найти длину окружности L и площадь круга S заданного радиуса R:\nL = 2·π·R, S = π·R^2.\nВ качестве значения π использовать 3.14.', NULL, 1, 256, 'Одно вещественное число: R.', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: L, S.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nR = float(input())\nprint(f\"{2*3.14*R:.2f}\")\nprint(f\"{3.14*R**2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(49, NULL, 'Begin8', 'Даны два числа a и b. Найти их среднее арифметическое: (a + b)/2.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: a, b (в этом порядке).', 'Одно вещественное число (среднее), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b = data\nprint(f\"{(a+b)/2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(50, NULL, 'Begin9', 'Даны два неотрицательных числа a и b. Найти их среднее геометрическое, т. е. квадратный корень из их произведения: (a·b)^(1/2).', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: a, b (в этом порядке).', 'Одно вещественное число (среднее геометрическое), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b = data\nprint(f\"{math.sqrt(a*b):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(51, NULL, 'Begin10', 'Даны два ненулевых числа. Найти сумму, разность, произведение и частное их квадратов.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: a, b (в этом порядке).', '4 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: сумма, разность, произведение, частное.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b = data\nprint(f\"{a**2+b**2:.2f}\")\nprint(f\"{a**2-b**2:.2f}\")\nprint(f\"{a**2*b**2:.2f}\")\nprint(f\"{a**2/b**2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(52, NULL, 'Begin11', 'Даны два ненулевых числа. Найти сумму, разность, произведение и частное их модулей.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: a, b (в этом порядке).', '4 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: сумма, разность, произведение, частное.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b = data\nprint(f\"{abs(a)+abs(b):.2f}\")\nprint(f\"{abs(a)-abs(b):.2f}\")\nprint(f\"{abs(a)*abs(b):.2f}\")\nprint(f\"{abs(a)/abs(b):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(53, NULL, 'Begin12', 'Даны катеты прямоугольного треугольника a и b. Найти его гипотенузу c и периметр P:\nc = (a^2 + b^2)^(1/2), P = a + b + c.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: a, b (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: c, P.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\na, b = data\nprint(f\"{math.sqrt(a**2+b**2):.2f}\")\nprint(f\"{a+b+math.sqrt(a**2+b**2):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(54, NULL, 'Begin13', 'Даны два круга с общим центром и радиусами R1 и R2 (R1 > R2). Найти площади этих кругов S1 и S2, а также площадь S3 кольца, внешний радиус которого равен R1, а внутренний радиус равен R2:\nS1 = π·(R1)^2, S2 = π·(R2)^2, S3 = S1 − S2.\nВ качестве значения π использовать 3.14.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: R1, R2 (в этом порядке).', '3 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: S1, S2, S3.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nR1, R2 = data\nprint(f\"{3.14*R1**2:.2f}\")\nprint(f\"{3.14*R2**2:.2f}\")\nprint(f\"{3.14*R1**2-3.14*R2**2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(55, NULL, 'Begin14', 'Дана длина L окружности. Найти ее радиус R и площадь S круга, ограниченного этой окружностью, учитывая, что L = 2·π·R, S = π·R^2. В качестве значения π использовать 3.14.', NULL, 1, 256, 'Одно вещественное число: L.', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: R, S.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nL = float(input())\nprint(f\"{L/(2*3.14):.2f}\")\nprint(f\"{3.14*(L/(2*3.14))**2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(56, NULL, 'Begin15', 'Дана площадь S круга. Найти его диаметр D и длину L окружности, ограничивающей этот круг, учитывая, что L = π·D, S = π·D^2/4. В качестве значения π использовать 3.14.', NULL, 1, 256, 'Одно вещественное число: S.', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: D, L.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nS = float(input())\nprint(f\"{math.sqrt(4*S/3.14):.2f}\")\nprint(f\"{3.14*math.sqrt(4*S/3.14):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(57, NULL, 'Begin16', 'Найти расстояние между двумя точками с заданными координатами x1 и x2 на числовой оси: |x2 − x1|.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: x1, x2 (в этом порядке).', 'Одно вещественное число (расстояние), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nx1, x2 = data\nprint(f\"{abs(x2-x1):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(58, NULL, 'Begin17', 'Даны три точки A, B, C на числовой оси. Найти длины отрезков AC и BC и их сумму.', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: A, B, C (в этом порядке).', '3 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: AC, BC, AC+BC.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B, C = data\nprint(f\"{abs(C-A):.2f}\")\nprint(f\"{abs(C-B):.2f}\")\nprint(f\"{abs(C-A)+abs(C-B):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(59, NULL, 'Begin18', 'Даны три точки A, B, C на числовой оси. Точка C расположена между точками A и B. Найти произведение длин отрезков AC и BC.', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: A, B, C (в этом порядке).', 'Одно вещественное число (AC*BC), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B, C = data\nprint(f\"{abs(C-A)*abs(C-B):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(60, NULL, 'Begin19', 'Даны координаты двух противоположных вершин прямоугольника: (x1, y1), (x2, y2). Стороны прямоугольника параллельны осям координат. Найти периметр и площадь данного прямоугольника.', NULL, 1, 256, '4 вещественных числа, каждое в отдельной строке: x1, y1, x2, y2 (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: P, S.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nx1, y1, x2, y2 = data\nprint(f\"{2*(abs(x2-x1)+abs(y2-y1)):.2f}\")\nprint(f\"{abs(x2-x1)*abs(y2-y1):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(61, NULL, 'Begin20', 'Найти расстояние между двумя точками с заданными координатами (x1, y1) и (x2, y2) на плоскости. Расстояние вычисляется по формуле\n((x2 − x1)^2 + (y2 − y1)^2)^(1/2).', NULL, 1, 256, '4 вещественных числа, каждое в отдельной строке: x1, y1, x2, y2 (в этом порядке).', 'Одно вещественное число (расстояние), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nx1, y1, x2, y2 = data\nprint(f\"{math.sqrt((x2-x1)**2+(y2-y1)**2):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(62, NULL, 'Begin21', 'Даны координаты трех вершин треугольника: (x1, y1), (x2, y2), (x3, y3). Найти его периметр и площадь, используя формулу для расстояния между двумя точками на плоскости (см. задание Begin20). Для нахождения площади треугольника со сторонами a, b, c использовать формулу Герона:\nS = (p·(p − a)·(p − b)·(p − c))^(1/2),\nгде p = (a + b + c)/2 — полупериметр.', NULL, 1, 256, '6 вещественных чисел, каждое в отдельной строке: x1, y1, x2, y2, x3, y3 (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: P, S.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nx1, y1, x2, y2, x3, y3 = data\na = math.sqrt((x2-x1)**2+(y2-y1)**2)\nb = math.sqrt((x3-x2)**2+(y3-y2)**2)\nc = math.sqrt((x1-x3)**2+(y1-y3)**2)\np = (a+b+c)/2\nprint(f\"{a+b+c:.2f}\")\nprint(f\"{math.sqrt(p*(p-a)*(p-b)*(p-c)):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(63, NULL, 'Begin22', 'Поменять местами содержимое переменных A и B и вывести новые значения A и B.', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: A, B (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: A, B.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B = data\nprint(f\"{B:.2f}\")\nprint(f\"{A:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(64, NULL, 'Begin23', 'Даны переменные A, B, C. Изменить их значения, переместив содержимое A в B, B — в C, C — в A, и вывести новые значения переменных A, B, C.', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: A, B, C (в этом порядке).', '3 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: A, B, C.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B, C = data\nprint(f\"{C:.2f}\")\nprint(f\"{A:.2f}\")\nprint(f\"{B:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(65, NULL, 'Begin24', 'Даны переменные A, B, C. Изменить их значения, переместив содержимое A в C, C — в B, B — в A, и вывести новые значения переменных A, B, C.', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: A, B, C (в этом порядке).', '3 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: A, B, C.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B, C = data\nprint(f\"{B:.2f}\")\nprint(f\"{C:.2f}\")\nprint(f\"{A:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(66, NULL, 'Begin25', 'Найти значение функции y = 3x^6 − 6x^2 − 7 при данном значении x.', NULL, 1, 256, 'Одно вещественное число: x.', 'Одно вещественное число (y), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nx = float(input())\nprint(f\"{3*x**6-6*x**2-7:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(67, NULL, 'Begin26', 'Найти значение функции y = 4(x−3)^6 − 7(x−3)^3 + 2 при данном значении x.', NULL, 1, 256, 'Одно вещественное число: x.', 'Одно вещественное число (y), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nx = float(input())\nprint(f\"{4*(x-3)**6-7*(x-3)**3+2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(68, NULL, 'Begin27', 'Дано число A. Вычислить A^8, используя вспомогательную переменную и три операции умножения. Для этого последовательно находить A^2, A^4, A^8. Вывести все найденные степени числа A.', NULL, 1, 256, 'Одно вещественное число: A.', '3 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: A^2, A^4, A^8.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nA = float(input())\nprint(f\"{A**2:.2f}\")\nprint(f\"{A**4:.2f}\")\nprint(f\"{A**8:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(69, NULL, 'Begin28', 'Дано число A. Вычислить A^(15), используя две вспомогательные переменные и пять операций умножения. Для этого последовательно находить A^2, A^3, A^5, A^(10), A^(15). Вывести все найденные степени числа A.', NULL, 1, 256, 'Одно вещественное число: A.', '5 вещественных чисел, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: A^2, A^3, A^5, A^10, A^15.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nA = float(input())\nprint(f\"{A**2:.2f}\")\nprint(f\"{A**3:.2f}\")\nprint(f\"{A**5:.2f}\")\nprint(f\"{A**10:.2f}\")\nprint(f\"{A**15:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(70, NULL, 'Begin29', 'Дано значение угла α в градусах (0 ≤ α < 360). Определить значение этого же угла в радианах, учитывая, что 180° = π радианов. В качестве значения π использовать 3.14.', NULL, 1, 256, 'Одно вещественное число: alpha.', 'Одно вещественное число (радианы), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nalpha = float(input())\nprint(f\"{alpha*3.14/180:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(71, NULL, 'Begin30', 'Дано значение угла α в радианах (0 ≤ α < 2·π). Определить значение этого же угла в градусах, учитывая, что 180° = π радианов. В качестве значения π использовать 3.14.', NULL, 1, 256, 'Одно вещественное число: alpha.', 'Одно вещественное число (градусы), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nalpha = float(input())\nprint(f\"{alpha*180/3.14:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(72, NULL, 'Begin31', 'Дано значение температуры T в градусах Фаренгейта. Определить значение этой же температуры в градусах Цельсия. Температура по Цельсию TC и температура по Фаренгейту TF связаны следующим соотношением:\nTC = (TF − 32)·5/9.', NULL, 1, 256, 'Одно вещественное число: T.', 'Одно вещественное число (TC), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nT = float(input())\nprint(f\"{(T-32)*5/9:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(73, NULL, 'Begin32', 'Дано значение температуры T в градусах Цельсия. Определить значение этой же температуры в градусах Фаренгейта. Температура по Цельсию TC и температура по Фаренгейту TF связаны следующим соотношением:\nTC = (TF − 32)·5/9.', NULL, 1, 256, 'Одно вещественное число: T.', 'Одно вещественное число (TF), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\nT = float(input())\nprint(f\"{T*9/5+32:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(74, NULL, 'Begin33', 'Известно, что X кг конфет стоит A рублей. Определить, сколько стоит 1 кг и Y кг этих же конфет.', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: X, A, Y (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: цена 1 кг, цена Y кг.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nX, A, Y = data\nprint(f\"{A/X:.2f}\")\nprint(f\"{A/X*Y:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(75, NULL, 'Begin34', 'Известно, что X кг шоколадных конфет стоит A рублей, а Y кг ирисок стоит B рублей. Определить, сколько стоит 1 кг шоколадных конфет, 1 кг ирисок, а также во сколько раз шоколадные конфеты дороже ирисок.', NULL, 1, 256, '4 вещественных числа, каждое в отдельной строке: X, A, Y, B (в этом порядке).', '3 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: цена 1 кг конфет, цена 1 кг ирисок, во сколько раз дороже.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nX, A, Y, B = data\nprint(f\"{A/X:.2f}\")\nprint(f\"{B/Y:.2f}\")\nprint(f\"{(A/X)/(B/Y):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(76, NULL, 'Begin35', 'Скорость лодки в стоячей воде V км/ч, скорость течения реки U км/ч (U < V). Время движения лодки по озеру T1 ч, а по реке (против течения) — T2 ч. Определить путь S, пройденный лодкой (путь = время · скорость). Учесть, что при движении против течения скорость лодки уменьшается на величину скорости течения.', NULL, 1, 256, '4 вещественных числа, каждое в отдельной строке: V, U, T1, T2 (в этом порядке).', 'Одно вещественное число (S), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nV, U, T1, T2 = data\nprint(f\"{V*T1+(V-U)*T2:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(77, NULL, 'Begin36', 'Скорость первого автомобиля V1 км/ч, второго — V2 км/ч, расстояние между ними S км. Определить расстояние между ними через T часов, если автомобили удаляются друг от друга, двигаясь в противоположных направлениях. Данное расстояние равно сумме начального расстояния и общего пути, проделанного автомобилями; общий путь = время · суммарная скорость.', NULL, 1, 256, '4 вещественных числа, каждое в отдельной строке: V1, V2, S, T (в этом порядке).', 'Одно вещественное число (расстояние), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nV1, V2, S, T = data\nprint(f\"{S+(V1+V2)*T:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(78, NULL, 'Begin37', 'Скорость первого автомобиля V1 км/ч, второго — V2 км/ч, расстояние между ними S км. Определить расстояние между ними через T часов, если автомобили первоначально движутся навстречу друг другу. Данное расстояние равно модулю разности начального расстояния и общего пути, проделанного автомобилями; общий путь = время · суммарная скорость.', NULL, 1, 256, '4 вещественных числа, каждое в отдельной строке: V1, V2, S, T (в этом порядке).', 'Одно вещественное число (расстояние), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nV1, V2, S, T = data\nprint(f\"{abs(S-(V1+V2)*T):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(79, NULL, 'Begin38', 'Решить линейное уравнение A·x + B = 0, заданное своими коэффициентами A и B (коэффициент A не равен 0).', NULL, 1, 256, '2 вещественных числа, каждое в отдельной строке: A, B (в этом порядке).', 'Одно вещественное число (x), записанное ровно с двумя знаками после десятичной точки.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B = data\nprint(f\"{-B/A:.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(80, NULL, 'Begin39', 'Найти корни квадратного уравнения A·x^2 + B·x + C = 0, заданного своими коэффициентами A, B, C (A > 0), если известно, что дискриминант уравнения положителен. Вывести вначале меньший, а затем больший из найденных корней. Корни квадратного уравнения находятся по формуле\nx1, 2 = (−B ± (D)^(1/2))/(2·A),\nгде D — дискриминант, равный B^2 − 4·A·C.', NULL, 1, 256, '3 вещественных числа, каждое в отдельной строке: A, B, C (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: меньший корень, больший корень.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA, B, C = data\nprint(f\"{(-B-math.sqrt(B**2-4*A*C))/(2*A):.2f}\")\nprint(f\"{(-B+math.sqrt(B**2-4*A*C))/(2*A):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(81, NULL, 'Begin40', 'Найти решение системы линейных уравнений вида\nA1·x + B1·y = C1,\nA2·x + B2·y = C2,\nзаданной своими коэффициентами A1, B1, C1, A2, B2, C2, если известно, что данная система имеет единственное решение. Воспользоваться формулами\nx = (C1·B2 − C2·B1)/D, y = (A1·C2 − A2·C1)/D,\nгде D = A1·B2 − A2·B1.', NULL, 1, 256, '6 вещественных чисел, каждое в отдельной строке: A1, B1, C1, A2, B2, C2 (в этом порядке).', '2 вещественных числа, каждое в отдельной строке, ровно с двумя знаками после десятичной точки, в порядке: x, y.', 100, 0, '2026-09-30 17:09:48', '2026-09-30 17:09:48', 14, 'easy', 'import math\n\ndata = []\nfor token in __import__(\"sys\").stdin.read().split():\n    data.append(float(token))\nA1, B1, C1, A2, B2, C2 = data\nprint(f\"{(C1*B2-C2*B1)/(A1*B2-A2*B1):.2f}\")\nprint(f\"{(A1*C2-A2*C1)/(A1*B2-A2*B1):.2f}\")\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:48', 0),
(82, NULL, 'Integer1', 'Дано расстояние L в сантиметрах. Используя операцию деления нацело, найти количество полных метров в нем (1 метр = 100 см).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (L).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(L):\n    return L // 100\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(83, NULL, 'Integer2', 'Дана масса M в килограммах. Используя операцию деления нацело, найти количество полных тонн в ней (1 тонна = 1000 кг).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (M).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(M):\n    return M // 1000\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(84, NULL, 'Integer3', 'Дан размер файла в байтах. Используя операцию деления нацело, найти количество полных килобайтов, которые занимает данный файл (1 килобайт = 1024 байта).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (size).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(size):\n    return size // 1024\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(85, NULL, 'Integer4', 'Даны целые положительные числа A и B (A > B). На отрезке длины A размещено максимально возможное количество отрезков длины B (без наложений). Используя операцию деления нацело, найти количество отрезков B, размещенных на отрезке A.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (A); целое число (B).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(A, B):\n    return A // B\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nx1 = int(L[p]); p += 1\nres = solve(x0, x1)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(86, NULL, 'Integer5', 'Даны целые положительные числа A и B (A > B). На отрезке длины A размещено максимально возможное количество отрезков длины B (без наложений). Используя операцию взятия остатка от деления нацело, найти длину незанятой части отрезка A.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (A); целое число (B).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(A, B):\n    return A % B\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nx1 = int(L[p]); p += 1\nres = solve(x0, x1)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0);
INSERT INTO `problems` (`id`, `contest_id`, `title`, `statement`, `notes`, `time_limit`, `memory_limit`, `input`, `output`, `score`, `order_index`, `created_at`, `updated_at`, `skill_id`, `complexity`, `solution_source`, `solution_language_id`, `tests_status`, `tests_log`, `tests_generated_at`, `hidden_from_archive`) VALUES
(87, NULL, 'Integer6', 'Дано двузначное число. Вывести вначале его левую цифру (десятки), а затем — его правую цифру (единицы). Для нахождения десятков использовать операцию деления нацело, для нахождения единиц — операцию взятия остатка от деления.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число; целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return (n // 10, n % 10)\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res[0]))\nprint(int(res[1]))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(88, NULL, 'Integer7', 'Дано двузначное число. Найти сумму и произведение его цифр.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число; целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return (n // 10 + n % 10, n // 10 * (n % 10))\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res[0]))\nprint(int(res[1]))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(89, NULL, 'Integer8', 'Дано двузначное число. Вывести число, полученное при перестановке цифр исходного числа.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 10 * 10 + n // 10\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(90, NULL, 'Integer9', 'Дано трехзначное число. Используя одну операцию деления нацело, вывести первую цифру данного числа (сотни).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n // 100\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(91, NULL, 'Integer10', 'Дано трехзначное число. Вывести вначале его последнюю цифру (единицы), а затем — его среднюю цифру (десятки).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число; целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return (n % 10, n // 10 % 10)\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res[0]))\nprint(int(res[1]))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(92, NULL, 'Integer11', 'Дано трехзначное число. Найти сумму и произведение его цифр.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число; целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    a, b, c = (n // 100, n // 10 % 10, n % 10)\n    return (a + b + c, a * b * c)\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res[0]))\nprint(int(res[1]))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(93, NULL, 'Integer12', 'Дано трехзначное число. Вывести число, полученное при прочтении исходного числа справа налево.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 10 * 100 + n // 10 % 10 * 10 + n // 100\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(94, NULL, 'Integer13', 'Дано трехзначное число. В нем зачеркнули первую слева цифру и приписали ее справа. Вывести полученное число.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 100 * 10 + n // 100\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(95, NULL, 'Integer14', 'Дано трехзначное число. В нем зачеркнули первую справа цифру и приписали ее слева. Вывести полученное число.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 10 * 100 + n // 10\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(96, NULL, 'Integer15', 'Дано трехзначное число. Вывести число, полученное при перестановке цифр сотен и десятков исходного числа (например, 123 перейдет в 213).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    a, b, c = (n // 100, n // 10 % 10, n % 10)\n    return b * 100 + a * 10 + c\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(97, NULL, 'Integer16', 'Дано трехзначное число. Вывести число, полученное при перестановке цифр десятков и единиц исходного числа (например, 123 перейдет в 132).', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    a, b, c = (n // 100, n // 10 % 10, n % 10)\n    return a * 100 + c * 10 + b\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(98, NULL, 'Integer17', 'Дано целое число, большее 999. Используя одну операцию деления нацело и одну операцию взятия остатка от деления, найти цифру, соответствующую разряду сотен в записи этого числа.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n // 100 % 10\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(99, NULL, 'Integer18', 'Дано целое число, большее 999. Используя одну операцию деления нацело и одну операцию взятия остатка от деления, найти цифру, соответствующую разряду тысяч в записи этого числа.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n // 1000 % 10\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(100, NULL, 'Integer19', 'С начала суток прошло N секунд (N — целое). Найти количество полных минут, прошедших с начала суток.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n // 60\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(101, NULL, 'Integer20', 'С начала суток прошло N секунд (N — целое). Найти количество полных часов, прошедших с начала суток.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n // 3600\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(102, NULL, 'Integer21', 'С начала суток прошло N секунд (N — целое). Найти количество секунд, прошедших с начала последней минуты.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 60\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(103, NULL, 'Integer22', 'С начала суток прошло N секунд (N — целое). Найти количество секунд, прошедших с начала последнего часа.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 3600\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(104, NULL, 'Integer23', 'С начала суток прошло N секунд (N — целое). Найти количество полных минут, прошедших с начала последнего часа.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(n):\n    return n % 3600 // 60\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(105, NULL, 'Integer24', 'Дни недели пронумерованы следующим образом: 0 — воскресенье, 1 — понедельник, 2 — вторник, …, 6 — суббота. Дано целое число K, лежащее в диапазоне 1–365. Определить номер дня недели для K-го дня года, если известно, что в этом году 1 января было понедельником.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (k).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(k):\n    return k % 7\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(106, NULL, 'Integer25', 'Дни недели пронумерованы следующим образом: 0 — воскресенье, 1 — понедельник, 2 — вторник, …, 6 — суббота. Дано целое число K, лежащее в диапазоне 1–365. Определить номер дня недели для K-го дня года, если известно, что в этом году 1 января было четвергом.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (k).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(k):\n    return (k + 3) % 7\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(107, NULL, 'Integer26', 'Дни недели пронумерованы следующим образом: 1 — понедельник, 2 — вторник, …, 6 — суббота, 7 — воскресенье. Дано целое число K, лежащее в диапазоне 1–365. Определить номер дня недели для K-го дня года, если известно, что в этом году 1 января было вторником.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (k).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(k):\n    return k % 7 + 1\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(108, NULL, 'Integer27', 'Дни недели пронумерованы следующим образом: 1 — понедельник, 2 — вторник, …, 6 — суббота, 7 — воскресенье. Дано целое число K, лежащее в диапазоне 1–365. Определить номер дня недели для K-го дня года, если известно, что в этом году 1 января было субботой.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (k).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(k):\n    return (k + 4) % 7 + 1\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(109, NULL, 'Integer28', 'Дни недели пронумерованы следующим образом: 1 — понедельник, 2 — вторник, …, 6 — суббота, 7 — воскресенье. Дано целое число K, лежащее в диапазоне 1–365, и целое число N, лежащее в диапазоне 1–7. Определить номер дня недели для K-го дня года, если известно, что в этом году 1 января было днем недели с номером N.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (k); целое число (n).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(k, n):\n    return (n - 1 + k - 1) % 7 + 1\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nx1 = int(L[p]); p += 1\nres = solve(x0, x1)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(110, NULL, 'Integer29', 'Даны целые положительные числа A, B, C. На прямоугольнике размера A × B размещено максимально возможное количество квадратов со стороной C (без наложений). Найти количество квадратов, размещенных на прямоугольнике, а также площадь незанятой части прямоугольника.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (A); целое число (B); целое число (C).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число; целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(A, B, C):\n    cnt = A // C * (B // C)\n    return (cnt, A * B - cnt * C * C)\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nx1 = int(L[p]); p += 1\nx2 = int(L[p]); p += 1\nres = solve(x0, x1, x2)\nprint(int(res[0]))\nprint(int(res[1]))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(111, NULL, 'Integer30', 'Дан номер некоторого года (целое положительное число). Определить соответствующий ему номер столетия, учитывая, что, к примеру, началом 20 столетия был 1901 год.', NULL, 1, 256, 'Данные вводятся в порядке, указанном в условии, каждое с новой строки: целое число (year).', 'Результаты выводятся в порядке, указанном в условии, каждый с новой строки: целое число.', 100, 0, '2026-09-30 17:09:59', '2026-09-30 17:09:59', 14, 'easy', 'import math\nimport sys\n\ndef solve(year):\n    return (year - 1) // 100 + 1\n\nL = sys.stdin.read().split(\"\\n\")\np = 0\nx0 = int(L[p]); p += 1\nres = solve(x0)\nprint(int(res))\n', 2, 'ready', 'Импортировано из задачника Абрамяна: тестов 10.', '2026-09-30 17:09:59', 0),
(112, NULL, 'Сумма двух чисел', '<p>Даны два целых числа <b>a</b> и <b>b</b>. Выведите их сумму.</p>', NULL, 1, 256, 'В единственной строке через пробел записаны два целых числа a и b (|a|, |b| ≤ 10<sup>9</sup>).', 'Одно целое число — сумма a + b.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'a, b = map(int, input().split())\nprint(a + b)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(113, NULL, 'Приветствие', '<p>Дано имя человека (может состоять из нескольких слов). Выведите приветствие в формате <code>Hello, ИМЯ!</code></p>', NULL, 1, 256, 'Одна строка — имя: латинские буквы и пробелы между словами, длина от 1 до 50 символов. В начале и в конце строки пробелов нет.', 'Одна строка: <code>Hello, </code>, затем имя, затем восклицательный знак.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'name = input()\nprint(f\"Hello, {name}!\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 11.', '2026-10-04 15:18:06', 1),
(114, NULL, 'Три числа наоборот', '<p>Даны три целых числа. Выведите их в обратном порядке, каждое на отдельной строке.</p>', NULL, 1, 256, 'В одной строке через пробел три целых числа, каждое по модулю не больше 10<sup>9</sup>.', 'Три строки: третье число, второе число, первое число.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'a, b, c = input().split()\nprint(c)\nprint(b)\nprint(a)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 10.', '2026-10-04 15:18:06', 1),
(115, NULL, 'Среднее двух чисел', '<p>Даны два целых числа. Выведите их среднее арифметическое, <b>ровно с одним знаком</b> после десятичной точки (ответ всегда имеет вид <i>целое</i>.0 или <i>целое</i>.5).</p>', NULL, 1, 256, 'В одной строке через пробел два целых числа a и b (|a|, |b| ≤ 10<sup>9</sup>).', 'Одно число — (a + b) / 2 с одним знаком после точки.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'a, b = map(int, input().split())\ns = a + b\nsign = \"-\" if s < 0 else \"\"\nq, r = divmod(abs(s), 2)\nprint(f\"{sign}{q}.{5 * r}\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(116, NULL, 'Время в секундах', '<p>Прошло <b>h</b> часов, <b>m</b> минут и <b>s</b> секунд. Сколько всего секунд прошло?</p>', NULL, 1, 256, 'В одной строке три целых числа h, m, s (0 ≤ h ≤ 1000, 0 ≤ m, s ≤ 59).', 'Одно целое число — общее количество секунд.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'h, m, s = map(int, input().split())\nprint(h * 3600 + m * 60 + s)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 11.', '2026-10-04 15:18:06', 1),
(117, NULL, 'Часы, минуты, секунды', '<p>Задано количество секунд <b>n</b>. Выведите время в формате <code>Ч:ММ:СС</code>: часы без ведущих нулей (их может быть больше 24), минуты и секунды всегда двумя цифрами.</p>', NULL, 1, 256, 'Одно целое число n (0 ≤ n ≤ 10<sup>9</sup>).', 'Одна строка в формате Ч:ММ:СС.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'n = int(input())\nprint(f\"{n // 3600}:{n % 3600 // 60:02d}:{n % 60:02d}\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 13.', '2026-10-04 15:18:06', 1),
(118, NULL, 'Конфеты поровну', '<p>У Миши есть <b>n</b> конфет, и он раздаёт их поровну <b>k</b> друзьям так, чтобы каждому досталось одинаковое количество. Сколько конфет получит каждый друг и сколько конфет останется у Миши?</p>', NULL, 1, 256, 'В одной строке два целых числа n и k (0 ≤ n ≤ 10<sup>9</sup>, 1 ≤ k ≤ 10<sup>9</sup>).', 'Два целых числа через пробел: сколько получит каждый друг и сколько останется.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'n, k = map(int, input().split())\nprint(n // k, n % k)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(119, NULL, 'Максимум из трёх', '<p>Даны три целых числа. Выведите наибольшее из них.</p>', NULL, 1, 256, 'В одной строке через пробел три целых числа, каждое по модулю не больше 10<sup>9</sup>.', 'Одно целое число — максимум.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'print(max(map(int, input().split())))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(120, NULL, 'Високосный год', '<p>Год високосный, если он делится на 4, но не делится на 100, либо делится на 400. Определите, високосный ли заданный год.</p>', NULL, 1, 256, 'Одно целое число — год y (1 ≤ y ≤ 9999).', 'Слово <code>YES</code>, если год високосный, иначе <code>NO</code>.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'y = int(input())\nprint(\"YES\" if (y % 4 == 0 and y % 100 != 0) or y % 400 == 0 else \"NO\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 13.', '2026-10-04 15:18:06', 1),
(121, NULL, 'Тип треугольника', '<p>Даны длины трёх отрезков. Определите, можно ли составить из них невырожденный треугольник (площадь строго положительна), и если можно — какого он типа.</p>', NULL, 1, 256, 'В одной строке через пробел три целых числа a, b, c (1 ≤ a, b, c ≤ 10<sup>9</sup>).', '<code>NO</code> — если треугольник составить нельзя; иначе <code>EQUILATERAL</code> (равносторонний), <code>ISOSCELES</code> (равнобедренный, но не равносторонний) или <code>SCALENE</code> (разносторонний).', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'medium', 'a, b, c = sorted(map(int, input().split()))\nif a + b <= c:\n    print(\"NO\")\nelif a == b == c:\n    print(\"EQUILATERAL\")\nelif a == b or b == c:\n    print(\"ISOSCELES\")\nelse:\n    print(\"SCALENE\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 19.', '2026-10-04 15:18:06', 1),
(122, NULL, 'Четверть плоскости', '<p>Дана точка с координатами (<b>x</b>, <b>y</b>), не лежащая на осях координат. Определите номер координатной четверти, в которой она находится (I — обе координаты положительны, II — x &lt; 0, y &gt; 0, III — обе отрицательны, IV — x &gt; 0, y &lt; 0).</p>', NULL, 1, 256, 'В одной строке два ненулевых целых числа x и y (|x|, |y| ≤ 10<sup>9</sup>).', 'Одно число от 1 до 4 — номер четверти.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'x, y = map(int, input().split())\nif x > 0 and y > 0:\n    print(1)\nelif x < 0 < y:\n    print(2)\nelif x < 0 and y < 0:\n    print(3)\nelse:\n    print(4)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 14.', '2026-10-04 15:18:06', 1),
(123, NULL, 'Сумма от 1 до n', '<p>Найдите сумму всех целых чисел от 1 до <b>n</b> включительно.</p>', NULL, 1, 256, 'Одно целое число n (1 ≤ n ≤ 10<sup>6</sup>).', 'Одно целое число — сумма 1 + 2 + … + n.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'n = int(input())\ntotal = 0\nfor i in range(1, n + 1):\n    total += i\nprint(total)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 11.', '2026-10-04 15:18:06', 1),
(124, NULL, 'Количество делителей', '<p>Найдите количество натуральных делителей числа <b>n</b> (включая 1 и само число).</p>', NULL, 1, 256, 'Одно целое число n (1 ≤ n ≤ 10<sup>6</sup>).', 'Одно целое число — количество делителей n.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'medium', 'n = int(input())\ncount = 0\nfor d in range(1, n + 1):\n    if n % d == 0:\n        count += 1\nprint(count)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 14.', '2026-10-04 15:18:06', 1),
(125, NULL, 'Числа Фибоначчи', '<p>Последовательность Фибоначчи задаётся так: F<sub>1</sub> = 1, F<sub>2</sub> = 1, F<sub>k</sub> = F<sub>k−1</sub> + F<sub>k−2</sub>. Найдите F<sub>n</sub>.</p>', NULL, 1, 256, 'Одно целое число n (1 ≤ n ≤ 90).', 'Одно целое число — F<sub>n</sub>.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'n = int(input())\na, b = 1, 1\nfor _ in range(n - 2):\n    a, b = b, a + b\nprint(b if n > 1 else 1)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(126, NULL, 'Таблица умножения', '<p>Выведите таблицу умножения числа <b>n</b> на числа от 1 до 10 в формате <code>n * i = результат</code>, по одной строке на каждое умножение.</p>', NULL, 1, 256, 'Одно целое число n (−1000 ≤ n ≤ 1000).', 'Десять строк вида <code>n * i = результат</code>, где i = 1, 2, …, 10.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 17, 'easy', 'n = int(input())\nfor i in range(1, 11):\n    print(f\"{n} * {i} = {n * i}\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 10.', '2026-10-04 15:18:06', 1),
(127, NULL, 'Сумма цифр', '<p>Найдите сумму десятичных цифр числа <b>n</b>.</p>', NULL, 1, 256, 'Одно целое число n (0 ≤ n ≤ 10<sup>18</sup>).', 'Одно число — сумма цифр n.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 18, 'easy', 'n = input().strip()\nprint(sum(int(c) for c in n))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(128, NULL, 'Число наоборот', '<p>Запишите цифры числа <b>n</b> в обратном порядке и выведите получившееся число. Ведущие нули результата отбрасываются (например, для 1200 ответ 21).</p>', NULL, 1, 256, 'Одно целое число n (0 ≤ n ≤ 10<sup>18</sup>).', 'Одно целое число — n, записанное задом наперёд, без ведущих нулей.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 18, 'easy', 'n = input().strip()\nprint(int(n[::-1]))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(129, NULL, 'Палиндром', '<p>Число называется палиндромом, если его десятичная запись читается одинаково слева направо и справа налево. Определите, является ли число <b>n</b> палиндромом.</p>', NULL, 1, 256, 'Одно целое число n (0 ≤ n ≤ 10<sup>18</sup>).', '<code>YES</code>, если n — палиндром, иначе <code>NO</code>.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 18, 'easy', 'n = input().strip()\nprint(\"YES\" if n == n[::-1] else \"NO\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(130, NULL, 'Максимум и его позиция', '<p>Дан массив из <b>n</b> целых чисел. Найдите наибольший элемент и номер его <b>первого</b> вхождения (нумерация с единицы).</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 1000). Во второй строке — n целых чисел, по модулю не превосходящих 10<sup>9</sup>.', 'Два числа через пробел: значение максимума и номер его первого вхождения.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 19, 'easy', 'n = int(input())\na = list(map(int, input().split()))\nm = max(a)\nprint(m, a.index(m) + 1)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(131, NULL, 'Разворот массива', '<p>Выведите элементы массива в обратном порядке.</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 1000). Во второй строке — n целых чисел, по модулю не превосходящих 10<sup>9</sup>.', 'Одна строка: n чисел через пробел в обратном порядке.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 19, 'easy', 'n = int(input())\na = input().split()\nprint(\" \".join(reversed(a)))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 8.', '2026-10-04 15:18:06', 1),
(132, NULL, 'Количество различных', '<p>Сколько различных значений встречается в массиве?</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 1000). Во второй строке — n целых чисел, по модулю не превосходящих 10<sup>9</sup>.', 'Одно число — количество различных значений.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 19, 'easy', 'n = int(input())\na = input().split()\nprint(len(set(map(int, a))))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 9.', '2026-10-04 15:18:06', 1),
(133, NULL, 'Лучшая серия', '<p>В массиве из <b>n</b> чисел выберите <b>k</b> подряд идущих элементов с наибольшей суммой. Выведите эту сумму.</p>', NULL, 1, 256, 'В первой строке записаны числа n и k (1 ≤ k ≤ n ≤ 2000). Во второй строке — n целых чисел, по модулю не превосходящих 10<sup>6</sup>.', 'Одно число — максимальная сумма k подряд идущих элементов.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 19, 'medium', 'n, k = map(int, input().split())\na = list(map(int, input().split()))\ncur = sum(a[:k])\nbest = cur\nfor i in range(k, n):\n    cur += a[i] - a[i - k]\n    best = max(best, cur)\nprint(best)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 11.', '2026-10-04 15:18:06', 1),
(134, NULL, 'Отсортируйте числа', '<p>Расположите числа в порядке неубывания.</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 2000). Во второй строке — n целых чисел, по модулю не превосходящих 10<sup>9</sup>.', 'Одна строка: n чисел через пробел в порядке неубывания.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 20, 'easy', 'n = int(input())\na = list(map(int, input().split()))\na.sort()\nprint(\" \".join(map(str, a)))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(135, NULL, 'Медиана', '<p>Медианой набора из нечётного числа элементов называется средний элемент после упорядочивания по возрастанию. Найдите медиану данного набора.</p>', NULL, 1, 256, 'В первой строке записано нечётное число n (1 ≤ n ≤ 1999). Во второй строке — n целых чисел, по модулю не превосходящих 10<sup>9</sup>.', 'Одно число — медиана.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 20, 'easy', 'n = int(input())\na = sorted(map(int, input().split()))\nprint(a[n // 2])\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 11.', '2026-10-04 15:18:06', 1),
(136, NULL, 'Максимум подарков', '<p>В магазине <b>n</b> подарков, цена <i>i</i>-го равна p<sub>i</sub>. У вас есть <b>m</b> монет. Какое наибольшее количество <b>разных</b> подарков можно купить?</p>', NULL, 1, 256, 'В первой строке записаны числа n и m (1 ≤ n ≤ 2000, 1 ≤ m ≤ 10<sup>9</sup>). Во второй строке — n цен p<sub>i</sub> (1 ≤ p<sub>i</sub> ≤ 10<sup>9</sup>).', 'Одно число — наибольшее количество подарков.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 20, 'medium', 'n, m = map(int, input().split())\np = sorted(map(int, input().split()))\ntotal = 0\ncount = 0\nfor x in p:\n    if total + x > m:\n        break\n    total += x\n    count += 1\nprint(count)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 12.', '2026-10-04 15:18:06', 1),
(137, NULL, 'Есть ли число', '<p>Дан отсортированный по неубыванию массив и несколько запросов. Для каждого запроса определите, встречается ли число в массиве.</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 2000), во второй — n целых чисел в порядке неубывания. В третьей строке — число запросов q (1 ≤ q ≤ 1000), в четвёртой — q целых чисел x. Все числа по модулю не превосходят 10<sup>9</sup>.', 'q строк: для каждого запроса <code>YES</code> или <code>NO</code>.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 11, 'medium', 'import bisect\nn = int(input())\na = list(map(int, input().split()))\nq = int(input())\nfor x in map(int, input().split()):\n    i = bisect.bisect_left(a, x)\n    print(\"YES\" if i < n and a[i] == x else \"NO\")\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 9.', '2026-10-04 15:18:06', 1),
(138, NULL, 'Первое вхождение', '<p>Дан отсортированный по неубыванию массив и несколько запросов. Для каждого запроса выведите номер (с единицы) <b>первого</b> вхождения числа в массив или −1, если такого числа нет.</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 2000), во второй — n целых чисел в порядке неубывания. В третьей строке — число запросов q (1 ≤ q ≤ 1000), в четвёртой — q целых чисел x. Все числа по модулю не превосходят 10<sup>9</sup>.', 'q строк: для каждого запроса номер первого вхождения или −1.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 11, 'medium', 'import bisect\nn = int(input())\na = list(map(int, input().split()))\nq = int(input())\nfor x in map(int, input().split()):\n    i = bisect.bisect_left(a, x)\n    print(i + 1 if i < n and a[i] == x else -1)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 9.', '2026-10-04 15:18:06', 1),
(139, NULL, 'Сколько не больше', '<p>Дан отсортированный по неубыванию массив и несколько запросов. Для каждого запроса x выведите, сколько элементов массива <b>не превосходят</b> x.</p>', NULL, 1, 256, 'В первой строке записано число n (1 ≤ n ≤ 2000), во второй — n целых чисел в порядке неубывания. В третьей строке — число запросов q (1 ≤ q ≤ 1000), в четвёртой — q целых чисел x. Все числа по модулю не превосходят 10<sup>9</sup>.', 'q строк: для каждого запроса количество элементов, не превосходящих x.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 11, 'medium', 'import bisect\nn = int(input())\na = list(map(int, input().split()))\nq = int(input())\nfor x in map(int, input().split()):\n    print(bisect.bisect_right(a, x))\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 9.', '2026-10-04 15:18:06', 1),
(140, NULL, 'Целый корень', '<p>Найдите наибольшее целое число <b>x</b>, для которого x² ≤ n. Не используйте вещественную арифметику: для больших n она теряет точность.</p>', NULL, 1, 256, 'Одно целое число n (0 ≤ n ≤ 10<sup>18</sup>).', 'Одно целое число — ⌊√n⌋.', 100, 0, '2026-10-04 15:18:06', '2026-10-04 15:18:06', 11, 'medium', 'n = int(input())\nlo, hi = 0, 10 ** 9 + 1\nwhile lo < hi:\n    mid = (lo + hi + 1) // 2\n    if mid * mid <= n:\n        lo = mid\n    else:\n        hi = mid - 1\nprint(lo)\n', 2, 'ready', 'Импортировано из маршрута. Тестов: 19.', '2026-10-04 15:18:06', 1);
