(257, 309, 5, 18, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n#define se second\r\n#define fi first\r\nusing namespace std;\r\nll Mod=1000000007;\r\nll binpow(ll x,ll y){\r\n    ll res=1;\r\n    while(y>0){\r\n        if(y%2==1){\r\n            res=res*x%Mod;\r\n        }\r\n        x*=x;\r\n        x%=Mod;\r\n        y/=2;\r\n    }\r\n    return res;\r\n}\r\nstruct segtree{\r\n    vector<ll>tree;\r\n    ll sz=1;\r\n    ll k=0;\r\n    void init(ll n){\r\n        while(sz<n) sz*=2,k++;\r\n        tree=vector<ll>(sz*2);\r\n    }\r\n    void initt(vector<ll>&a){\r\n        for(ll i=1; i<a.size(); i++) tree[i+sz-1]=a[i];\r\n        for(ll i=sz-1; i>=1; i--) tree[i]=__gcd(tree[i*2],tree[i*2+1]);\r\n    }\r\n    ll mxx=0;\r\n    void Get1(ll x,ll l,ll r,ll L,ll R){\r\n        if(L>r || R<l)  return;\r\n        if(L<=l && r<=R){\r\n            mxx=__gcd(mxx,tree[x]);\r\n            return;\r\n        }\r\n        ll M=(l+r)/2;\r\n        Get1(x*2,l,M,L,R);\r\n        Get1(x*2+1,M+1,r,L,R);\r\n    }\r\n    ll Get_Max(ll l,ll r){\r\n        mxx=0;\r\n        Get1(1,1,sz,l,r);\r\n        return mxx;\r\n    }\r\n    void Print(){\r\n    for(ll i=1; i<=2*sz-1; i++){\r\n        cout<<i<<\" \"<<tree[i]<<\"\\n\";\r\n    }\r\n    }\r\n};\r\nbool prime(ll x){\r\n    if(x==1) return 0;\r\n    for(ll i=2; i*i<=x; i++){\r\n        if(x%i==0) return 0;\r\n    }\r\n    return 1;\r\n}\r\nll lcm(ll x,ll y){\r\n    return x*y/__gcd(x,y);\r\n}\r\nvector<ll>Fact(3e5+1);\r\nvector<ll>Fact1(3e5+1);\r\nll C(ll n,ll k){\r\n    if(n<k) return 0;\r\n    return Fact[n]*Fact1[k]%Mod*Fact1[n-k]%Mod;\r\n}\r\nstruct cmp{\r\n    bool operator()(const ll a,const ll b)const{\r\n        return a>=b;\r\n    }\r\n};\r\n\r\nstruct cmpp{\r\n    bool operator()(const pair<ll,ll>a,const pair<ll,ll>b)const{\r\n        if(a.second-a.first==b.second-b.first) return a.first>b.first;\r\n        return a.second-a.first+1<b.second-b.first+1;\r\n    }\r\n};\r\nbool Cmp(pair<ll,ll>a,p