(292, 309, 7, 30, 1, 'import sys\r\n\r\ndef solve():\r\n    input_data = sys.stdin.read().split()\r\n    if not input_data:\r\n        return\r\n    \r\n    n = int(input_data[0])\r\n    k = int(input_data[1])\r\n    \r\n    arr = [int(x) for x in input_data[2:n+2]]\r\n    queries = [int(x) for x in input_data[n+2:n+2+k]]\r\n    \r\n    out = []\r\n    for q in queries:\r\n        left = 0\r\n        right = n - 1\r\n        found = False\r\n        \r\n        while left <= right:\r\n            mid = (left + right) // 2\r\n            if arr[mid] == q:\r\n                found = True\r\n                break\r\n            elif arr[mid] < q:\r\n                left = mid + 1\r\n            else:\r\n                right = mid - 1\r\n        \r\n        if found:\r\n            out.append(\"YES\")\r\n        else:\r\n            out.append(\"NO\")\r\n            \r\n    print(\'\\n\'.join(out))\r\n\r\nif __name__ == \'__main__\':\r\n    solve()', 'completed_error', 0, 0, 0, 0, '2026-09-10 07:15:13', '2026-09-10 07:15:13', NULL),
(293, 309, 7, 30, 1, '#include <iostream>\r\n#include <vector>\r\n\r\nusing namespace std;\r\n\r\nint main() {\r\n    ios_base::sync_with_stdio(false);\r\n    cin.tie(NULL);\r\n\r\n    int n, k;\r\n    if (!(cin >> n >> k)) return 0;\r\n\r\n    vector<int> arr(n);\r\n    for (int i = 0; i < n; ++i) {\r\n        cin >> arr[i];\r\n    }\r\n\r\n    for (int i = 0; i < k; ++i) {\r\n        int q;\r\n        cin >> q;\r\n\r\n        int left = 0;\r\n        int right = n - 1;\r\n        bool found = false;\r\n\r\n        while (left <= right) {\r\n            int mid = left + (right - left) / 2;\r\n            if (arr[mid] == q) {\r\n                found = true;\r\n                break;\r\n            } else if (arr[mid] < q) {\r\n                left = mid + 1;\r\n            } else {\r\n                right = mid - 1;\r\n            }\r\n        }\r\n\r\n        if (found) {\r\n            cout << \"YES\\n\";\r\n        } else {\r\n            cout << \"NO\\n\";\r\n        }\r\n    }\r\n\r\n    return 0;\r\n}', 'wrong_answer', 0, 3, 1, 1872, '2026-09-10 07:15:31', '2026-09-10 07:15:32', NULL),
(294, 309, 7, 30, 1, '#include <iostream>\r\n#include <vector>\r\nusing namespace std;\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, k;\r\n    cin >> n >> k;\r\n\r\n    vector<long long> a(n);\r\n    for (int i = 0; i < n; ++i) {\r\n        cin >> a[i];\r\n    }\r\n\r\n    while (k--) {\r\n        long long q;\r\n        cin >> q;\r\n\r\n        int left = 0, right = n - 1;\r\n        bool found = false;\r\n\r\n        while (left <= right) {\r\n            int mid = left + (right - left) / 2;\r\n            if (a[mid] == q) {\r\n                found = true;\r\n                break;\r\n            } else if (a[mid] < q) {\r\n                left = mid + 1;\r\n            } else {\r\n                right = mid - 1;\r\n            }\r\n        }\r\n\r\n        cout << (found ? \"YES\" : \"NO\") << \'\\n\';\r\n    }\r\n\r\n    return 0;\r\n}', 'wrong_answer', 0, 3, 1, 1868, '2026-09-10 07:35:21', '2026-09-10 07:35:22', NULL),
(295, 3, 7, 30, 1, '#include <iostream>\r\n#include <vector>\r\nusing namespace std;\r\n\r\nbool binarySearch(const vector<long long>& a, long long x) {\r\n    int left = 0;\r\n    int right = a.size() - 1;\r\n\r\n    while (left <= right) {\r\n        int mid = left + (right - left) / 2;\r\n\r\n        if (a[mid] == x) {\r\n            return true;\r\n        }\r\n\r\n        if (a[mid] < x) {\r\n            left = mid + 1;\r\n        } else {\r\n            right = mid - 1;\r\n        }\r\n    }\r\n\r\n    return false;\r\n}\r\n\r\nint main() {\r\n    ios::sync_with_stdio(false);\r\n    cin.tie(nullptr);\r\n\r\n    int n, k;\r\n    cin >> n >> k;\r\n\r\n    vector<long long> a(n);\r\n\r\n    for (int i = 0; i < n; i++) {\r\n        cin >> a[i];\r\n    }\r\n\r\n    for (int i = 0; i < k; i++) {\r\n        long long x;\r\n        cin >> x;\r\n\r\n        if (binarySearch(a, x)) {\r\n            cout << \"YES\\n\";\r\n        } else {\r\n            cout << \"NO\\n\";\r\n        }\r\n    }\r\n\r\n    return 0;\r\n}', 'wrong_answer', 0, 3, 1, 1840, '2026-09-10 07:59:43', '2026-09-10 07:59:44', NULL),
