(304, 309, 7, 33, 1, '#include <bits/stdc++.h>\r\nusing namespace std;\r\n\r\n#define ll long long\r\n\r\nint main() {\r\n    ll n;\r\n    cin >> n;\r\n\r\n    vector<ll> a(n);\r\n\r\n    for (ll i = 0; i < n; i++) {\r\n        cin >> a[i];\r\n    }\r\n\r\n    sort(a.begin(), a.end());\r\n\r\n    ll k;\r\n    cin >> k;\r\n\r\n    while (k--) {\r\n        ll l, r;\r\n        cin >> l >> r;\r\n\r\n        ll left = 0, right = n - 1;\r\n        ll L = n;\r\n\r\n        while (left <= right) {\r\n            ll m = (left + right) / 2;\r\n\r\n            if (a[m] >= l) {\r\n                L = m;\r\n                right = m - 1;\r\n            } else {\r\n                left = m + 1;\r\n            }\r\n        }\r\n\r\n        left = 0;\r\n        right = n - 1;\r\n        ll R = n;\r\n\r\n        while (left <= right) {\r\n            ll m = (left + right) / 2;\r\n\r\n            if (a[m] > r) {\r\n                R = m;\r\n                right = m - 1;\r\n            } else {\r\n                left = m + 1;\r\n            }\r\n        }\r\n\r\n        cout << R - L << \'\\n\';\r\n    }\r\n\r\n    return 0;\r\n}', 'accepted', 0, 30, 880, 1868, '2026-09-10 08:39:32', '2026-09-10 08:39:47', NULL),
