(306, 3, 8, 34, 1, '#include <iostream>\r\nusing namespace std;\r\n\r\nusing ll = long long;\r\n\r\nbool canFit(ll x, ll w, ll h, ll n) {\r\n    return (x / w) >= (n + (x / h) - 1) / (x / h);\r\n}\r\n\r\nint main() {\r\n    ll w, h, n;\r\n    cin >> w >> h >> n;\r\n\r\n    ll left = 0;\r\n    ll right = max(w, h) * n;\r\n\r\n    while (left < right) {\r\n        ll mid = left + (right - left) / 2;\r\n\r\n        ll rows = mid / h;\r\n        ll cols = mid / w;\r\n\r\n        // Защита от деления на 0 и переполнения\r\n        bool possible = false;\r\n\r\n        if (rows > 0 && cols > 0) {\r\n            if (cols >= (n + rows - 1) / rows)\r\n                possible = true;\r\n        }\r\n\r\n        if (possible)\r\n            right = mid;\r\n        else\r\n            left = mid + 1;\r\n    }\r\n\r\n    cout << left << \'\\n\';\r\n\r\n    return 0;\r\n}', 'accepted', 0, 30, 1, 1876, '2026-09-10 13:36:15', '2026-09-10 13:36:17', NULL),
(307, 309, 8, 34, 1, '#include <iostream>\r\nusing namespace std;\r\n\r\nint main() {\r\n    long long w, h, n;\r\n    cin >> w >> h >> n;\r\n\r\n    auto can = [&](long long side) -> bool {\r\n        __int128 cnt = (__int128)(side / w) * (side / h);\r\n        return cnt >= n;\r\n    };\r\n\r\n    long long lo = 0, hi = max(w, h) * n;\r\n    while (lo < hi) {\r\n        long long mid = lo + (hi - lo) / 2;\r\n        if (can(mid)) hi = mid;\r\n        else lo = mid + 1;\r\n    }\r\n\r\n    cout << lo << \'\\n\';\r\n    return 0;\r\n}', 'accepted', 0, 30, 1, 1872, '2026-09-10 14:35:56', '2026-09-10 14:35:57', NULL),
