(1789, 318, 5, 18, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n#define fi first\r\n#define se second\r\n#define int long long\r\nusing namespace std;\r\n\r\nconst int mod=1e9+7;\r\n\r\nvoid input(vector<int> &a,int i=0){\r\n    if(i==a.size())return;\r\n    cin>>a[i];\r\n    input(a,i+1);\r\n}\r\n\r\nvoid print(vector<int> &a,int i=0){\r\n    if(i==a.size())return;\r\n    cout<<a[i]<<\" \";\r\n    print(a,i+1);\r\n}\r\n\r\nistream& operator>>(istream &i,__int128 &x){\r\n    string s;\r\n    i>>s;\r\n    x=0;\r\n    for(char j:s)x=x*10+(j-\'0\');\r\n    return i;\r\n}\r\n\r\nostream& operator<<(ostream& i,__int128 x){\r\n    if(x==0)return i<<0;\r\n    string s;\r\n    while(x!=0){\r\n        s.push_back(char(\'0\'+x%10));\r\n        x/=10;\r\n    }\r\n    reverse(s.begin(),s.end());\r\n    return i<<s;\r\n}\r\n\r\nvector<int> p;\r\nint cmp(int a,int b){\r\n    return p[a]<p[b];\r\n}\r\n\r\nvoid bfs() {\r\n    int n;\r\n    cin>>n;\r\n    vector<vector<int>> g(n+1);\r\n    p=vector<int> (n+1);\r\n    for(int i=0;i<n-1;i++){\r\n        int u,v;\r\n        cin>>u>>v;\r\n        g[u].push_back(v);\r\n        g[v].push_back(u);\r\n    }\r\n    vector<int> a(n);\r\n    for(int i=0;i<a.size();i++){\r\n        cin>>a[i];\r\n        p[a[i]]=i;\r\n    }\r\n    if(a[0]!=1){\r\n        cout<<\"NO\\n\";\r\n        return;\r\n    }\r\n    for(int i=1;i<=n;i++)sort(g[i].begin(),g[i].end(),cmp);\r\n    queue<int> q;\r\n    vector<int> used(n+1),b;\r\n    q.push(1);\r\n    used[1]=1;\r\n    while(q.size()){\r\n        int v=q.front();\r\n        q.pop();\r\n        b.push_back(v);\r\n        for(auto u:g[v]){\r\n            if(used[u])continue;\r\n            used[u]=1;\r\n            q.push(u);\r\n        }\r\n    }\r\n    cout<<(a==b ? \"YES\":\"NO\");\r\n}\r\n\r\n\r\nint gcd(int a,int b){\r\n    if(b==0)return a;\r\n    return gcd(b,a%b);\r\n}\r\n\r\nchar f(int x){\r\n    if(x<10)return char(\'0\'+x);\r\n    return char(\'a\'+x-10);\r\n\r\n}\r\n\r\n//int n,m,k,cnt;\r\n//vector<vector<char>> a;\r\n//\r\n//void dfs(int i,int j){\r\n//    if(i<0 or j<0 or i>=n or j>=m)return;\r\n//    if(a[i][j]!=\'.\')return;\r\n//    if(!cnt)return;\r\n//    a[i][j]=\'*\';\r\n//    cnt--;\r\n//    dfs(i+1,j);\r\n//    dfs(i-1,j);\r\n//    dfs(i,j+1);\r\n//    dfs(i,j-1);\r\n//}\r\n\r\n\r\n//int n;\r\n//vector<int> a;\r\n//\r\n//void rec(int s,int l){\r\n//    if(s==n){\r\n//        print(a);\r\n//        cout<<\"\\n\";\r\n//        return;\r\n//    }\r\n//    for(int i=n-s;i>=l;i--){\r\n//        a.push_back(i);\r\n//        rec(s+i,i);\r\n//        a.pop_back();\r\n//    }\r\n//}\r\n\r\n\r\nint fact(int n){\r\n    int s=1;\r\n    for(int i=1;i<=n;i++)s*=i;\r\n    return s;\r\n}\r\n\r\nvector<int> dp;\r\n\r\nvoid F(int n){\r\n    if(n==0){\r\n        dp[0]=1;\r\n        return;\r\n    }\r\n    if(dp[n]!=-1)return;\r\n    if(n%2!=0){\r\n        F(n-1);\r\n        dp[n]=dp[n-1];\r\n    }\r\n    else{\r\n        F(n-1);\r\n        F(n/2);\r\n        dp[n]=dp[n-1]+dp[n/2];\r\n    }\r\n}\r\n\r\nint C(int n,int k){\r\n    return fact(n)/(fact(n-k)*fact(k));\r\n}\r\n\r\nint n,k;\r\nint mx=0;\r\n\r\nvoid rec(int i,int j){\r\n    if(i==k){\r\n        mx++;\r\n        return;\r\n    }\r\n    for(int k=j;k<=n;k+=j)rec(i+1,k);\r\n}\r\n\r\n\r\nvoid Main(){\r\n    string s;\r\n    cin>>s;\r\n    reverse(s.begin(),s.end());\r\n    cout<<s;\r\n}\r\n\r\nsigned main() {\r\n    ios::sync_with_stdio(0);\r\n    cin.tie(0);\r\n    int T=1;\r\n    //cin>>T;\r\n    while(T--)Main();\r\n    return 0;\r\n}', 'accepted', 0, 5, 1, 1844, '2026-09-26 08:27:02', '2026-09-26 08:27:04', NULL),
(1790, 316, 9, 38, 1, '#pragma GCC optimize(\"Ofast,unroll-loops\")\r\n#include <iostream>\r\n#include <vector>\r\n#include <algorithm>\r\n#include <cmath>\r\n#include <cstring>\r\n#include <string>\r\n#include <map>\r\n#include <set>\r\n#include <queue>\r\n#include <stack>\r\n#include <deque>\r\n#include <unordered_map>\r\n#include <unordered_set>\r\n#include <iomanip>\r\n\r\n#define ll long long\r\n#define ld long double\r\n \r\nusing namespace std;\r\n\r\nvoid Faridun2011(){\r\n    ll n, k=0;\r\n    cin>>n;\r\n    for(ll i=0; i<n; i++){\r\n        for(ll j=0; j<n; j++){\r\n            ll a;\r\n            cin>>a;\r\n            if(a==1) k++;\r\n        }\r\n    }\r\n    cout<<k/2;\r\n}\r\n\r\nint main()\r\n{\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(0); cout.tie(0);\r\n    int t=1;\r\n    //cin>>t;\r\n    while(t--){\r\n        Faridun2011();\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 51, 1, 1872, '2026-09-26 08:27:53', '2026-09-26 08:27:55', NULL),
(1791, 317, 9, 38, 1, '#include<bits/stdc++.h>\r\n\r\n#pragma GCC optimize(\"Ofast,O3,unroll-loops\")\r\n#pragma GCC target(\"avx,avx2,bmi,bmi2,lzcnt,popcnt\")\r\n\r\n#define ll long long\r\n#define ull unsigned long long\r\n#define ld long double\r\n#define pb push_back\r\n#define all(a) a.begin(),a.end()\r\n#define rall(a) a.rbegin(),a.rend()\r\n\r\nconst ll MOD=1e9+7;\r\nconst ll Mod=998244353;\r\nconst ll INF=1e18;\r\nconst double PI=3.14159265358979323846;\r\n\r\nusing namespace std;\r\n\r\nbool prime(ll x){if(x<2)return false;for(ll i=2;i*i<=x;i++){if(x%i==0){\r\nreturn false;}}return true;}ll lcm(ll a,ll b){return a/__gcd(a,b)*b;}ll\r\nbinpow(ll a,ll k){a%=MOD;if(k==0){return 1;}ll s=1;while(k){if(k%2){\r\ns=(s*a)%MOD;}a=(a*a)%MOD;k/=2;}return s;}ll Minv(ll n){return binpow(n,MOD\r\n-2);}ll C(ll n,ll k){if(k<0 || k>n)return 0;if(k==0 || k==n)return 1;ll\r\na=1,b=1;for(ll i=0;i<k;i++){a=(a*((n-i)%MOD)+MOD)%MOD;b=(b*(i+1)+MOD)%MOD\r\n;}return(a*Minv(b)+MOD)%MOD;}ll Sum(ll a){ll k=0;while(a){k+=a%10;a/=10;}return k;}\r\n\r\nvoid ES(){\r\n  ll n;\r\n  cin>>n;\r\n  ll k=0;\r\n  for(ll i=0;i<n;i++){\r\n    for(ll j=0;j<n;j++){\r\n      ll x;\r\n      cin>>x;\r\n      k+=x;\r\n    }\r\n  }\r\n  cout<<k/2;\r\n}\r\n\r\nint main()\r\n{\r\n    //setlocale(LC_ALL,\"Rus\");\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(nullptr);\r\n    //cout<<fixed<<setprecision(12);\r\n    ll T=1;\r\n    //cin>>T;\r\n    while(T--){\r\n      ES();\r\n      cout<<\"\\n\";\r\n    }\r\n    return 0;\r\n}\r\n', 'accepted', 0, 51, 1, 1872, '2026-09-26 08:28:17', '2026-09-26 08:28:19', NULL);
