(1792, 309, 9, 38, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n#define se second\r\n#define fi first\r\nusing namespace std;\r\nll Mod=1000000007;\r\nll binpow(ll x,ll y){\r\n    ll res=1;\r\n    while(y>0){\r\n        if(y%2==1){\r\n            res=res*x%Mod;\r\n        }\r\n        x*=x;\r\n        x%=Mod;\r\n        y/=2;\r\n    }\r\n    return res;\r\n}\r\nbool prime(ll x){\r\n    if(x==1) return 0;\r\n    for(ll i=2; i*i<=x; i++){\r\n        if(x%i==0) return 0;\r\n    }\r\n    return 1;\r\n}\r\nll lcm(ll x,ll y){\r\n    return x*y/__gcd(x,y);\r\n}\r\nvector<ll>Fact(3e5+1);\r\nvector<ll>Fact1(3e5+1);\r\nll C(ll n,ll k){\r\n    if(n<k) return 0;\r\n    return Fact[n]*Fact1[k]%Mod*Fact1[n-k]%Mod;\r\n}\r\nstruct cmp{\r\n    bool operator()(const ll a,const ll b)const{\r\n        return a>=b;\r\n    }\r\n};\r\n\r\nstruct cmpp{\r\n    bool operator()(const pair<ll,ll>a,const pair<ll,ll>b)const{\r\n        if(a.second-a.first==b.second-b.first) return a.first>b.first;\r\n        return a.second-a.first+1<b.second-b.first+1;\r\n    }\r\n};\r\nbool Cmp(pair<ll,ll>a,pair<ll,ll>b){\r\n    if(a.first==b.first) return a.second<b.second;\r\n    return a.first>b.first;\r\n}\r\nll Sum_of_digits(ll x){\r\n    ll sum=0;\r\n    while(x>0){\r\n        sum+=x%10;\r\n        x/=10;\r\n    }\r\n    return sum;\r\n}\r\nll kol=0;\r\nvector<ll> Merge(vector<ll>a,vector<ll>b){\r\n    ll n=a.size(),m=b.size();\r\n    vector<ll>c(n+m);\r\n    ll l=0,r=0;\r\n    while(l<n || r<m){\r\n        if(r==m || (l<n && a[l]<=b[r])){\r\n            c[l+r]=a[l];\r\n            l++;\r\n        }\r\n        else{\r\n            c[l+r]=b[r];\r\n            kol+=n-l;\r\n            r++;\r\n        }\r\n    }\r\n    return c;\r\n}\r\nvector<ll> MergeSort(vector<ll>a){\r\n    if(a.size()<=1) return a;\r\n    vector<ll>b,c;\r\n    for(ll i=0; i<a.size()/2; i++) b.push_back(a[i]);\r\n    for(ll i=a.size()/2; i<a.size(); i++) c.push_back(a[i]);\r\n    return Merge(MergeSort(b),MergeSort(c));\r\n}\r\nstruct Node{\r\n    vector<ll>heap;\r\n    Node(ll len=200001){\r\n        heap.resize(len);\r\n    }\r\n    ll l=1;\r\n    void Insert(ll x){\r\n        heap[l]=x;\r\n        ll L=l;\r\n        while(L/2>=1 && heap[L/2]<heap[L]){\r\n            swap(heap[L/2],heap[L]);\r\n            L/=2;\r\n        }\r\n        l++;\r\n    }\r\n    void Extract(){\r\n        cout<<heap[1]<<\"\\n\";\r\n        swap(heap[1],heap[l-1]);\r\n        heap[l-1]=-1e17;\r\n        l--;\r\n        ll X=1,N=l-1;\r\n        while(X*2<=N){\r\n            ll left=X*2,right=X*2+1,q=left;\r\n            if(right<=N && heap[right]>heap[left]){\r\n                q++;\r\n            }\r\n            if(heap[X]<heap[q]){\r\n                swap(heap[X],heap[q]);\r\n                X=q;\r\n            }\r\n            else{\r\n                break;\r\n            }\r\n        }\r\n    }\r\n};\r\nvector<ll>p;\r\nvector<ll>w;\r\nvector<ll>mn;\r\nvector<ll>mx;\r\nll findparent(ll x){\r\n    if(x!=p[x]){\r\n        p[x]=findparent(p[x]);\r\n    }\r\n    return p[x];\r\n}\r\nvoid Union(ll x,ll y){\r\n    ll x1=findparent(x),y1=findparent(y);\r\n    if(x1!=y1){\r\n    if(w[x1]<w[y1]) swap(x1,y1);\r\n    w[x1]+=w[y1];\r\n    p[y1]=x1;\r\n    mn[x1]=min(mn[x1],mn[y1]);\r\n    mx[x1]=max(mx[x1],mx[y1]);\r\n    }\r\n}\r\nstruct PRS{\r\n    ll x,y;\r\n    char z;\r\n};\r\nbool CMPP(PRS a, PRS b){\r\n    if(a.x==b.x) return a.y<b.y;\r\n    return a.x<b.x;\r\n}\r\nvector<vector<ll> >a;\r\nvector<ll>tin,tout;\r\nvector<ll>d;\r\nll LOG=20;\r\nvector<vector<ll> >up;\r\nvoid DFS(ll x,ll y){\r\n    tin[x]=++kol;\r\n    up[0][x]=y;\r\n    for(auto &i:a[x]){\r\n        if(i!=y){\r\n            DFS(i,x);\r\n        }\r\n    }\r\n    tout[x]=++kol;\r\n}\r\nbool F(ll u,ll v){\r\n    return tin[u]<=tin[v] && tout[v]<=tout[u];\r\n}\r\nll LCA(ll u,ll v){\r\n    if(F(u,v)) return u;\r\n    if(F(v,u)) return v;\r\n    for(ll i=LOG-1; i>=0; i--){\r\n        if(!F(up[i][u],v)){\r\n            u=up[i][u];\r\n        }\r\n    }\r\n    return up[0][u];\r\n}\r\nstruct ABD{\r\n    ll A,B,D;\r\n};\r\nll dist(ll u,ll v){\r\n    ll w=LCA(u,v);\r\n    return d[u]+d[v]-2*d[w];\r\n}\r\nstruct segtree{\r\n    vector<ll> tree;\r\n    ll sz=1;\r\n\r\n    void init(ll n){\r\n        while(sz<n) sz*=2;\r\n\r\n        tree=vector<ll>(2*sz);\r\n    }\r\n    void initt(vector<ll>&a){\r\n        for(ll i=1; i<a.size(); i++) tree[i+sz-1]=a[i];\r\n        for(ll i=sz-1; i>=1; i--) tree[i]=(tree[i*2]&tree[i*2+1]);\r\n    }\r\n    void Set(ll ind ,ll x){\r\n        ll w=sz+ind-1;\r\n        tree[w]+=x;\r\n        w/=2;\r\n        while(w>0){\r\n            tree[w]=tree[w*2]+tree[w*2+1];\r\n            w/=2;\r\n        }\r\n    }\r\n    ll S=-1;\r\n    void Sum(ll x,ll l,ll r,ll L1,ll R1){\r\n        if(L1>r || R1<l) return;\r\n        if(l<=L1 && r>=R1){\r\n            if(S==-1){\r\n            S=tree[x];\r\n            }\r\n            else{\r\n                S&=tree[x];\r\n            }\r\n            return;\r\n        }\r\n        ll m=(L1+R1)/2;\r\n        Sum(x*2,l,r,L1,m);\r\n        Sum(x*2+1,l,r,m+1,R1);\r\n    }\r\n    ll Sum(ll l, ll r){\r\n        S=-1;\r\n        Sum(1,l,r,1,sz);\r\n        return S;\r\n    }\r\n    /*void Get1(ll x,ll l,ll r,ll L,ll R,\r\n              ll &sm,ll &pr,ll &sf,ll &ans){\r\n\r\n        if(L>r || R<l) return;\r\n\r\n        if(L<=l && r<=R){\r\n            sm=sum[x];\r\n            pr=pref[x];\r\n            sf=suff[x];\r\n            ans=mx[x];\r\n            return;\r\n        }\r\n\r\n        ll M=(l+r)/2;\r\n\r\n        if(R<=M){\r\n            Get1(x*2,l,M,L,R,sm,pr,sf,ans);\r\n        }\r\n        else if(L>M){\r\n            Get1(x*2+1,M+1,r,L,R,sm,pr,sf,ans);\r\n        }\r\n        else{\r\n            ll sm1,pr1,sf1,ans1;\r\n            ll sm2,pr2,sf2,ans2;\r\n\r\n            Get1(x*2,l,M,L,R,sm1,pr1,sf1,ans1);\r\n            Get1(x*2+1,M+1,r,L,R,sm2,pr2,sf2,ans2);\r\n\r\n            sm=sm1+sm2;\r\n\r\n            pr=max(pr1,sm1+pr2);\r\n\r\n            sf=max(sf2,sm2+sf1);\r\n\r\n            ans=max({ans1,ans2,sf1+pr2});\r\n        }\r\n    }\r\n\r\n    ll Get_Max(ll l,ll r){\r\n        ll sm,pr,sf,ans;\r\n\r\n        Get1(1,1,sz,l,r,sm,pr,sf,ans);\r\n\r\n        return ans;\r\n    }*/\r\n};\r\nvoid __Naimjon__(){\r\n    for(ll i=1; i<1e9; i++)\r\n    ll n;\r\n    cin>>n;\r\n    ll kol=0;\r\n    for(ll i=0; i<n*n; i++){\r\n        ll x;\r\n        cin>>x;\r\n        kol+=x;\r\n    }\r\n    cout<<kol/2;\r\n\r\n}\r\nint main(){\r\n    /*Fact[0]=Fact[1]=1;\r\n    for(ll i=2; i<=3e5; i++){\r\n        Fact[i]=Fact[i-1]*i;\r\n        Fact[i]%=Mod;\r\n    }\r\n    Fact1[3e5]=binpow(Fact[3e5],Mod-2);\r\n    for(ll i=3e5-1; i>=0; i--){\r\n        Fact1[i]=(Fact1[i+1]*(i+1))%Mod;\r\n    }*/\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(0);\r\n    ll T=1;\r\n    cin>>T;\r\n    while(T--) __Naimjon__(),cout<<\"\\n\";\r\n    return 0;\r\n}', 'completed_error', 0, 0, 0, 0, '2026-09-26 08:28:52', '2026-09-26 08:28:53', NULL),
