][u];\r\n        }\r\n    }\r\n    return up[0][u];\r\n}\r\nstruct ABD{\r\n    ll A,B,D;\r\n};\r\nll dist(ll u,ll v){\r\n    ll w=LCA(u,v);\r\n    return d[u]+d[v]-2*d[w];\r\n}\r\nstruct segtree{\r\n    vector<ll> tree;\r\n    ll sz=1;\r\n\r\n    void init(ll n){\r\n        while(sz<n) sz*=2;\r\n\r\n        tree=vector<ll>(2*sz);\r\n    }\r\n    void initt(vector<ll>&a){\r\n        for(ll i=1; i<a.size(); i++) tree[i+sz-1]=a[i];\r\n        for(ll i=sz-1; i>=1; i--) tree[i]=(tree[i*2]&tree[i*2+1]);\r\n    }\r\n    void Set(ll ind ,ll x){\r\n        ll w=sz+ind-1;\r\n        tree[w]+=x;\r\n        w/=2;\r\n        while(w>0){\r\n            tree[w]=tree[w*2]+tree[w*2+1];\r\n            w/=2;\r\n        }\r\n    }\r\n    ll S=-1;\r\n    void Sum(ll x,ll l,ll r,ll L1,ll R1){\r\n        if(L1>r || R1<l) return;\r\n        if(l<=L1 && r>=R1){\r\n            if(S==-1){\r\n            S=tree[x];\r\n            }\r\n            else{\r\n                S&=tree[x];\r\n            }\r\n            return;\r\n        }\r\n        ll m=(L1+R1)/2;\r\n        Sum(x*2,l,r,L1,m);\r\n        Sum(x*2+1,l,r,m+1,R1);\r\n    }\r\n    ll Sum(ll l, ll r){\r\n        S=-1;\r\n        Sum(1,l,r,1,sz);\r\n        return S;\r\n    }\r\n    /*void Get1(ll x,ll l,ll r,ll L,ll R,\r\n              ll &sm,ll &pr,ll &sf,ll &ans){\r\n\r\n        if(L>r || R<l) return;\r\n\r\n        if(L<=l && r<=R){\r\n            sm=sum[x];\r\n            pr=pref[x];\r\n            sf=suff[x];\r\n            ans=mx[x];\r\n            return;\r\n        }\r\n\r\n        ll M=(l+r)/2;\r\n\r\n        if(R<=M){\r\n            Get1(x*2,l,M,L,R,sm,pr,sf,ans);\r\n        }\r\n        else if(L>M){\r\n            Get1(x*2+1,M+1,r,L,R,sm,pr,sf,ans);\r\n        }\r\n        else{\r\n            ll sm1,pr1,sf1,ans1;\r\n            ll sm2,pr2,sf2,ans2;\r\n\r\n            Get1(x*2,l,M,L,R,sm1,pr1,sf1,ans1);\r\n            Get1(x*2+1,M+1,r,L,R,sm2,pr2,sf2,ans2);\r\n\r\n            sm=sm1+sm2;\r\n\r\n            pr=max(pr1,sm1+pr