(1815, 315, 9, 38, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define fi first\r\n#define se second\r\n\r\nusing namespace std;\r\n\r\nvoid pigeon(){\r\n    ll n,kol=0;\r\n    cin>>n;\r\n    vector<vector<ll>>a(n,vector<ll>(n));\r\n    for(ll i=0; i<n; i++){\r\n        for(ll k=0; k<n; k++){\r\n            cin>>a[i][k];\r\n            if(a[i][k])kol++;\r\n        }\r\n    }\r\n    cout<<kol/2;\r\n}\r\nint main(){\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(0);cout.tie(0);\r\n    ll t=1;\r\n    //cin>>t;\r\n    while(t--){\r\n        pigeon();\r\n    }\r\n}', 'accepted', 0, 51, 1, 1868, '2026-09-26 08:45:08', '2026-09-26 08:45:10', NULL),
