(1820, 309, 9, 38, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n#define se second\r\n#define fi first\r\nusing namespace std;\r\nll Mod=1000000007;\r\nll binpow(ll x,ll y){\r\n    ll res=1;\r\n    while(y>0){\r\n        if(y%2==1){\r\n            res=res*x%Mod;\r\n        }\r\n        x*=x;\r\n        x%=Mod;\r\n        y/=2;\r\n    }\r\n    return res;\r\n}\r\nbool prime(ll x){\r\n    if(x==1) return 0;\r\n    for(ll i=2; i*i<=x; i++){\r\n        if(x%i==0) return 0;\r\n    }\r\n    return 1;\r\n}\r\nll lcm(ll x,ll y){\r\n    return x*y/__gcd(x,y);\r\n}\r\nvector<ll>Fact(3e5+1);\r\nvector<ll>Fact1(3e5+1);\r\nll C(ll n,ll k){\r\n    if(n<k) return 0;\r\n    return Fact[n]*Fact1[k]%Mod*Fact1[n-k]%Mod;\r\n}\r\nstruct cmp{\r\n    bool operator()(const ll a,const ll b)const{\r\n        return a>=b;\r\n    }\r\n};\r\n\r\nstruct cmpp{\r\n    bool operator()(const pair<ll,ll>a,const pair<ll,ll>b)const{\r\n        if(a.second-a.first==b.second-b.first) return a.first>b.first;\r\n        return a.second-a.first+1<b.second-b.first+1;\r\n    }\r\n};\r\nbool Cmp(pair<ll,ll>a,pair<ll,ll>b){\r\n    if(a.first==b.first) return a.second<b.second;\r\n    return a.first>b.first;\r\n}\r\nll Sum_of_digits(ll x){\r\n    ll sum=0;\r\n    while(x>0){\r\n        sum+=x%10;\r\n        x/=10;\r\n    }\r\n    return sum;\r\n}\r\nll kol=0;\r\nvector<ll> Merge(vector<ll>a,vector<ll>b){\r\n    ll n=a.size(),m=b.size();\r\n    vector<ll>c(n+m);\r\n    ll l=0,r=0;\r\n    while(l<n || r<m){\r\n        if(r==m || (l<n && a[l]<=b[r])){\r\n            c[l+r]=a[l];\r\n            l++;\r\n        }\r\n        else{\r\n            c[l+r]=b[r];\r\n            kol+=n-l;\r\n            r++;\r\n        }\r\n    }\r\n    return c;\r\n}\r\nvector<ll> MergeSort(vector<ll>a){\r\n    if(a.size()<=1) return a;\r\n    vector<ll>b,c;\r\n    for(ll i=0; i<a.size()/2; i++) b.push_back(a[i]);\r\n    for(ll i=a.size()/2; i<a.size(); i++) c.push_back(a[i]);\r\n    return Merge(MergeSort(b),MergeSort(c));\r\n}\r\nstruct Node{\r\n    vector<ll>heap;\r\n    Node(ll len=200001){\r\n        heap.resize(len);\r\n    }\r\n    ll l=1;\r\n    void Insert(ll x){\r\n        heap[l]=x;\r\n        ll L=l;\r\n        while(L/2>=1 && heap[L/2]<heap[L]){\r\n            swap(heap[L/2],heap[L]);\r\n            L/=2;\r\n        }\r\n        l++;\r\n    }\r\n    void Extract(){\r\n        cout<<heap[1]<<\"\\n\";\r\n        swap(heap[1],heap[l-1]);\r\n        heap[l-1]=-1e17;\r\n        l--;\r\n        ll X=1,N=l-1;\r\n        while(X*2<=N){\r\n            ll left=X*2,right=X*2+1,q=left;\r\n            if(right<=N && heap[right]>heap[left]){\r\n                q++;\r\n            }\r\n            if(heap[X]<heap[q]){\r\n                swap(heap[X],heap[q]);\r\n                X=q;\r\n            }\r\n            else{\r\n                break;\r\n            }\r\n        }\r\n    }\r\n};\r\nvector<ll>p;\r\nvector<ll>w;\r\nvector<ll>mn;\r\nvector<ll>mx;\r\nll findparent(ll x){\r\n    if(x!=p[x]){\r\n        p[x]=findparent(p[x]);\r\n    }\r\n    return p[x];\r\n}\r\nvoid Union(ll x,ll y){\r\n    ll x1=findparent(x),y1=findparent(y);\r\n    if(x1!=y1){\r\n    if(w[x1]<w[y1]) swap(x1,y1);\r\n    w[x1]+=w[y1];\r\n    p[y1]=x1;\r\n    mn[x1]=min(mn[x1],mn[y1]);\r\n    mx[x1]=max(mx[x1],mx[y1]);\r\n    }\r\n}\r\nstruct PRS{\r\n    ll x,y;\r\n    char z;\r\n};\r\nbool CMPP(PRS a, PRS b){\r\n    if(a.x==b.x) return a.y<b.y;\r\n    return a.x<b.x;\r\n}\r\nvector<vector<ll> >a;\r\nvector<ll>tin,tout;\r\nvector<ll>d;\r\nll LOG=20;\r\nvector<vector<ll> >up;\r\nvoid DFS(ll x,ll y){\r\n    tin[x]=++kol;\r\n    up[0][x]=y;\r\n    for(auto &i:a[x]){\r\n        if(i!=y){\r\n            DFS(i,x);\r\n        }\r\n    }\r\n    tout[x]=++kol;\r\n}\r\nbool F(ll u,ll v){\r\n    return tin[u]<=tin[v] && tout[v]<=tout[u];\r\n}\r\nll LCA(ll u,ll v){\r\n    if(F(u,v)) return u;\r\n    if(F(v,u)) return v;\r\n    for(ll i=LOG-1; i>=0; i--){\r\n        if(!F(up[i][u],v)){\r\n            u=up[i