(2030, 315, 9, 38, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define fi first\r\n#define se second\r\n\r\nusing namespace std;\r\n\r\nvoid pigeon(){\r\n    ll n,kol=0;\r\n    cin>>n;\r\n    vector<vector<ll>>a(n,vector<ll>(n));\r\n    for(ll i=0; i<n; i++){\r\n        for(ll k=0; k<n; k++){\r\n            cin>>a[i][k];\r\n            if(a[i][k])kol++;\r\n        }\r\n    }\r\n    cout<<kol/2;\r\n}\r\nint main(){\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(0);cout.tie(0);\r\n    ll t=1;\r\n    //cin>>t;\r\n    while(t--){\r\n        pigeon();\r\n    }\r\n}', 'accepted', 0, 51, 10, 1876, '2026-09-26 08:49:57', '2026-09-26 08:49:59', NULL),
(2031, 317, 9, 38, 1, '#include<bits/stdc++.h>\r\n\r\n#pragma GCC optimize(\"Ofast,O3,unroll-loops\")\r\n#pragma GCC target(\"avx,avx2,bmi,bmi2,lzcnt,popcnt\")\r\n\r\n#define ll long long\r\n#define ull unsigned long long\r\n#define ld long double\r\n#define pb push_back\r\n#define all(a) a.begin(),a.end()\r\n#define rall(a) a.rbegin(),a.rend()\r\n\r\nconst ll MOD=1e9+7;\r\nconst ll Mod=998244353;\r\nconst ll INF=1e18;\r\nconst double PI=3.14159265358979323846;\r\n\r\nusing namespace std;\r\n\r\nbool prime(ll x){if(x<2)return false;for(ll i=2;i*i<=x;i++){if(x%i==0){\r\nreturn false;}}return true;}ll lcm(ll a,ll b){return a/__gcd(a,b)*b;}ll\r\nbinpow(ll a,ll k){a%=MOD;if(k==0){return 1;}ll s=1;while(k){if(k%2){\r\ns=(s*a)%MOD;}a=(a*a)%MOD;k/=2;}return s;}ll Minv(ll n){return binpow(n,MOD\r\n-2);}ll C(ll n,ll k){if(k<0 || k>n)return 0;if(k==0 || k==n)return 1;ll\r\na=1,b=1;for(ll i=0;i<k;i++){a=(a*((n-i)%MOD)+MOD)%MOD;b=(b*(i+1)+MOD)%MOD\r\n;}return(a*Minv(b)+MOD)%MOD;}ll Sum(ll a){ll k=0;while(a){k+=a%10;a/=10;}return k;}\r\n\r\nvoid ES(){\r\n  ll n;\r\n  cin>>n;\r\n  ll k=0;\r\n  for(ll i=0;i<n;i++){\r\n    for(ll j=0;j<n;j++){\r\n      ll x;\r\n      cin>>x;\r\n      k+=x;\r\n    }\r\n  }\r\n  cout<<k/2;\r\n}\r\n\r\nint main()\r\n{\r\n    //setlocale(LC_ALL,\"Rus\");\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(nullptr);\r\n    //cout<<fixed<<setprecision(12);\r\n    ll T=1;\r\n    //cin>>T;\r\n    while(T--){\r\n      ES();\r\n      cout<<\"\\n\";\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 51, 1, 1872, '2026-09-26 08:49:58', '2026-09-26 08:50:01', NULL),
