(2153, 316, 9, 38, 1, '#pragma GCC optimize(\"Ofast,unroll-loops\")\r\n#include <iostream>\r\n#include <vector>\r\n#include <algorithm>\r\n#include <cmath>\r\n#include <cstring>\r\n#include <string>\r\n#include <map>\r\n#include <set>\r\n#include <queue>\r\n#include <stack>\r\n#include <deque>\r\n#include <unordered_map>\r\n#include <unordered_set>\r\n#include <iomanip>\r\n\r\n#define ll long long\r\n#define ld long double\r\n \r\nusing namespace std;\r\n\r\nvoid Faridun2011(){\r\n    ll n, k=0;\r\n    cin>>n;\r\n    for(ll i=0; i<n; i++){\r\n        for(ll j=0; j<n; j++){\r\n            ll a;\r\n            cin>>a;\r\n            if(a==1) k++;\r\n        }\r\n    }\r\n    cout<<k/2;\r\n}\r\n\r\nint main()\r\n{\r\n    ios_base::sync_with_stdio(0);\r\n    cin.tie(0); cout.tie(0);\r\n    int t=1;\r\n    //cin>>t;\r\n    while(t--){\r\n        Faridun2011();\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 51, 1, 1868, '2026-09-26 08:53:30', '2026-09-26 08:53:32', NULL),
