(2263, 343, 7, 30, 1, '#include <bits/stdc++.h>\r\n#define ll long ling\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\nbool binSearch(vector<int>& a, int x){\r\n    int l = -1;\r\n    int r = a.size();\r\n    while (l < r-1){\r\n        int mid = (l + r) / 2;\r\n        if (a[mid] > x)\r\n            r = mid;\r\n        else if (a[mid] < x)\r\n            l = mid;\r\n        else return 1;\r\n    }\r\n    return 0;\r\n}\r\n\r\nint main()\r\n{\r\n    int n, k;\r\n    cin >> n >> k;\r\n    vector<int> a(n, 0);\r\n\r\n    for (int &t : a)\r\n        cin >> t;\r\n\r\n    for (int i = 0; i < k; i++){\r\n        int x;\r\n        cin >> x;\r\n\r\n        if (binSearch(a, x))\r\n            cout << \"YES\" << endl;\r\n        else cout << \"NO\" << endl;\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 30, 790, 1872, '2026-10-18 13:25:18', '2026-10-18 13:25:28', NULL),
(2264, 343, 7, 31, 1, '#include <bits/stdc++.h>\r\n#define ll long ling\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\nint zadacha2(vector<int>& a, int x){\r\n    int l = -1;\r\n    int r = a.size();\r\n    \r\n    if (a[0] > x) return 0;\r\n    else if (a[r-1] <= x)return r;\r\n\r\n    while (l < r-1){\r\n        int mid = (l + r) / 2;\r\n\r\n        if (a[mid] > x)\r\n            r = mid;\r\n        else if (a[mid] <= x)\r\n            l = mid;\r\n    }\r\n    return r;\r\n}\r\nint main()\r\n{\r\n    int n, k;\r\n    cin >> n >> k;\r\n    vector<int> a(n, 0);\r\n\r\n    for (int &t : a)\r\n        cin >> t;\r\n\r\n    for (int i = 0; i < k; i++){\r\n        int x;\r\n        cin >> x;\r\n\r\n        cout << zadacha2(a, x) << endl;\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 30, 980, 1872, '2026-10-18 14:02:58', '2026-10-18 14:03:12', NULL),
(2265, 343, 7, 32, 1, '#include <bits/stdc++.h>\r\n#define ll long ling\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\nint zadacha3(vector<int>& a, int x){\r\n    int l = -1;\r\n    int r = a.size();\r\n\r\n    if (a[r-1] < x) return r+1;\r\n    else if (a[0] >= x) return 1;\r\n\r\n    while (l < r-1){\r\n        int mid = (l + r) / 2;\r\n\r\n        if (a[mid] >= x)\r\n            r = mid;\r\n        else if (a[mid] < x)\r\n            l = mid;\r\n    }\r\n    return r+1;\r\n}\r\nint main()\r\n{\r\n    int n, k;\r\n    cin >> n >> k;\r\n    vector<int> a(n, 0);\r\n\r\n    for (int &t : a)\r\n        cin >> t;\r\n\r\n    for (int i = 0; i < k; i++){\r\n        int x;\r\n        cin >> x;\r\n\r\n        cout << zadacha3(a, x) << endl;\r\n    }\r\n    return 0;\r\n}', 'time_limit_exceeded', 0, 17, 940, 1868, '2026-10-18 14:13:32', '2026-10-18 14:13:38', NULL),
(2266, 343, 7, 32, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\nll zadacha3(vector<ll>& a, ll x){\r\n    ll l = -1;\r\n    ll r = a.size();\r\n\r\n    if (a[r-1] < x) return r+1;\r\n    else if (a[0] >= x) return 1;\r\n\r\n    while (l < r-1){\r\n        ll mid = (l + r) / 2;\r\n\r\n        if (a[mid] >= x)\r\n            r = mid;\r\n        else if (a[mid] < x)\r\n            l = mid;\r\n    }\r\n    return r+1;\r\n}\r\nint main()\r\n{\r\n    ll n, k;\r\n    cin >> n >> k;\r\n    vector<ll> a(n, 0);\r\n\r\n    for (ll &t : a)\r\n        cin >> t;\r\n\r\n    for (ll i = 0; i < k; i++){\r\n        ll x;\r\n        cin >> x;\r\n\r\n        cout << zadacha3(a, x) << endl;\r\n    }\r\n    return 0;\r\n}', 'time_limit_exceeded', 0, 29, 900, 1872, '2026-10-18 14:15:51', '2026-10-18 14:16:05', NULL),
(2267, 343, 7, 32, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\nbool binSearch(vector<int>& a, int x){\r\n    int l = -1;\r\n    int r = a.size();\r\n    while (l < r-1){\r\n        int mid = (l + r) / 2;\r\n        if (a[mid] > x)\r\n            r = mid;\r\n        else if (a[mid] < x)\r\n            l = mid;\r\n        else return 1;\r\n    }\r\n    return 0;\r\n}\r\n\r\nll zadacha3(vector<ll>& a, ll x){\r\n    ll l = -1;\r\n    ll r = a.size();\r\n\r\n    if (a[r-1] < x) return r+1;\r\n    else if (a[0] >= x) return 1;\r\n\r\n    while (l < r-1){\r\n        ll mid = (r - l) / 2 + l;\r\n\r\n        if (a[mid] >= x)\r\n            r = mid;\r\n        else if (a[mid] < x)\r\n            l = mid;\r\n    }\r\n    return r+1;\r\n}\r\nint main()\r\n{\r\n    ll n, k;\r\n    cin >> n >> k;\r\n    vector<ll> a(n, 0);\r\n\r\n    for (ll &t : a)\r\n        cin >> t;\r\n\r\n    for (ll i = 0; i < k; i++){\r\n        ll x;\r\n        cin >> x;\r\n\r\n        cout << zadacha3(a, x) << endl;\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 30, 980, 1872, '2026-10-18 14:17:05', '2026-10-18 14:17:21', NULL),
(2268, 343, 7, 33, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\n\r\n\r\nll lowerBound(vector<ll>& a, ll x) {\r\n    ll l = 0;\r\n    ll r = a.size();\r\n\r\n    while (l < r) {\r\n        ll mid = l + (r - l) / 2;\r\n        if (a[mid] >= x)\r\n            r = mid;\r\n        else l = mid + 1;\r\n    }\r\n    return l;\r\n}\r\n\r\nll upperBound(vector<ll>& a, ll x) {\r\n    ll l = 0, r = a.size();\r\n\r\n    while (l < r) {\r\n        ll mid = l + (r - l) / 2;\r\n        if (a[mid] > x)\r\n            r = mid;\r\n        else l = mid + 1;\r\n    }\r\n\r\n    return l;\r\n}\r\n\r\nint main() {\r\n\r\n    ll n; cin >> n;\r\n    vector<ll> a(n);\r\n\r\n    for (ll &t : a)\r\n        cin >> t;\r\n\r\n    sort(a.begin(), a.end());\r\n\r\n    ll k; cin >> k;\r\n\r\n    while (k--) {\r\n        ll l, r;\r\n        cin >> l >> r;\r\n\r\n        ll left = lowerBound(a, l);\r\n        ll right = upperBound(a, r);\r\n\r\n        cout << right - left << \" \";\r\n    }\r\n\r\n    return 0;\r\n}', 'wrong_answer', 0, 3, 1, 1868, '2026-10-18 14:33:22', '2026-10-18 14:33:24', NULL),
(2269, 343, 7, 33, 1, '#include <bits/stdc++.h>\r\n#define ll long long\r\n#define ld long double\r\n\r\nusing namespace std;\r\n\r\nll lowerBound(vector<ll>& a, ll x) {\r\n    ll l = 0;\r\n    ll r = a.size();\r\n\r\n    while (l < r) {\r\n        ll mid = l + (r - l) / 2;\r\n        if (a[mid] >= x)\r\n            r = mid;\r\n        else l = mid + 1;\r\n    }\r\n    return l;\r\n}\r\n\r\nll upperBound(vector<ll>& a, ll x) {\r\n    ll l = 0;\r\n    ll r = a.size();\r\n\r\n    while (l < r) {\r\n        ll mid = l + (r - l) / 2;\r\n        if (a[mid] > x)\r\n            r = mid;\r\n        else l = mid + 1;\r\n    }\r\n    return l;\r\n}\r\n\r\nint main() {\r\n    ll n; cin >> n;\r\n    vector<ll> a(n);\r\n\r\n    for (ll &t : a)\r\n        cin >> t;\r\n    sort(a.begin(), a.end());\r\n    ll k; cin >> k;\r\n    while (k--) {\r\n        ll l, r;\r\n        cin >> l >> r;\r\n        ll left = lowerBound(a, l);\r\n        ll right = upperBound(a, r);\r\n        cout << right - left << endl;\r\n    }\r\n    return 0;\r\n}', 'accepted', 0, 30, 860, 1868, '2026-10-18 14:37:29', '2026-10-18 14:37:44', NULL);
